# =========================
# V28 DJ MESA COMO MENSAJE ESTABLE: EDITAR, NO BORRAR/RECREAR
# =========================
# Objetivo:
# - La mesa/cuadro de mandos se crea una vez y después se EDITA siempre.
# - El panel fijado superior se edita siempre y NO toca la mesa.
# - Cambiar canción, refrescar, añadir cola, abrir lista, etc. NO debe borrar la mesa.
# - Solo se crea mesa nueva si no hay message_id guardado o Telegram confirma que no existe.
# - Solo se oculta si se pulsa explícitamente ➖ Minimizar mesa.


def _is_msg_not_found_error_v28(exc: Exception) -> bool:
    err = str(exc).lower()
    return (
        'message to edit not found' in err
        or 'message_id_invalid' in err
        or 'message not found' in err
        or 'message identifier is not specified' in err
    )


async def _send_new_control_panel_v28(bot, chat_id: int) -> None:
    """Crea la mesa solo cuando no existe o Telegram confirmó que desapareció."""
    state = get_state(chat_id)
    text, markup = current_control_view(state)
    msg = await bot.send_message(
        chat_id=chat_id,
        text=text,
        reply_markup=markup,
        parse_mode=ParseMode.HTML,
    )
    state.control_message_id = msg.message_id
    admin_cfg(chat_id)["dj_mesa_visible"] = True
    admin_cfg(chat_id)["dj_mesa_minimized"] = False
    save_all_states()
    await register_bot_message(chat_id, msg.message_id)


async def _edit_control_panel_v28(bot, chat_id: int, *, force_create: bool = True) -> None:
    """Edita la mesa existente. No borra el mensaje anterior.

    Si la mesa fue borrada manualmente o no existe message_id, puede crear una nueva
    solo cuando force_create=True. Nunca usa safe_delete sobre la mesa.
    """
    state = get_state(chat_id)
    cfg = admin_cfg(chat_id)

    if bool(cfg.get("dj_mesa_minimized", False)):
        # Minimizada manualmente: no tocar, no recrear.
        return

    text, markup = current_control_view(state)

    if state.control_message_id:
        try:
            await bot.edit_message_text(
                chat_id=chat_id,
                message_id=state.control_message_id,
                text=text,
                reply_markup=markup,
                parse_mode=ParseMode.HTML,
            )
            cfg["dj_mesa_visible"] = True
            cfg["dj_mesa_minimized"] = False
            save_all_states()
            return
        except BadRequest as e:
            err = str(e).lower()
            if "message is not modified" in err:
                cfg["dj_mesa_visible"] = True
                cfg["dj_mesa_minimized"] = False
                save_all_states()
                return
            if _is_msg_not_found_error_v28(e):
                # El mensaje ya no existe. Solo aquí permitimos crear otro.
                state.control_message_id = None
                save_all_states()
            else:
                # Error temporal/HTML/etc. No crear duplicados.
                logger.warning("No se pudo editar mesa DJ %s en chat %s: %s", state.control_message_id, chat_id, e)
                return
        except Exception as e:
            logger.exception("Fallo temporal editando mesa DJ %s en chat %s; no se recrea.", state.control_message_id, chat_id)
            return

    if force_create and not state.control_message_id:
        await _send_new_control_panel_v28(bot, chat_id)


async def ensure_control_panel(bot, chat_id: int) -> None:
    """Mesa estable final: editar si existe; crear solo si no existe; nunca borrar."""
    cfg = admin_cfg(chat_id)
    state = get_state(chat_id)
    if not state.dj_mode:
        return
    if bool(cfg.get("dj_mesa_minimized", False)):
        return
    cfg["dj_mesa_visible"] = True
    cfg["dj_mesa_minimized"] = False
    save_all_states()
    await _edit_control_panel_v28(bot, chat_id, force_create=True)


async def render_control_home(bot, chat_id: int) -> None:
    """Vuelve a la vista home editando la misma mesa."""
    state = get_state(chat_id)
    state.dj_mode = True
    set_control_view(state, "home", 0)
    admin_cfg(chat_id)["dj_mesa_visible"] = True
