async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ""
    if q and data.startswith("cfg|"):
        parts = data.split("|")
        action = parts[1] if len(parts) > 1 else ""
        try:
            chat_id = int(parts[2]) if len(parts) > 2 and parts[2].lstrip('-').isdigit() else 0
        except Exception:
            chat_id = 0
        if action == "phrase_next":
            cfg_set(chat_id, "daily_phrase_offset", int(cfg_value(chat_id, "daily_phrase_offset", 0) or 0) + 1)
            await q.answer("Frase cambiada ✅")
            await q.edit_message_text(admin_private_block_text(chat_id, "daily_phrase"), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, "daily_phrase"))
            return
        if action == "phrase_reset":
            cfg_set(chat_id, "daily_phrase_offset", 0)
            await q.answer("Frase reiniciada ✅")
            await q.edit_message_text(admin_private_block_text(chat_id, "daily_phrase"), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, "daily_phrase"))
            return
        if action == "phrase_send":
            title = str(cfg_value(chat_id, 'daily_phrase_title', '🌞 Frase del día'))
            phrase = daily_phrase_for_chat_v30(chat_id)
            msg = await context.bot.send_message(chat_id, f"<b>{h(title)}</b>\n\n<i>{h(phrase)}</i>", parse_mode=ParseMode.HTML)
            await register_bot_message(chat_id, msg.message_id)
            await q.answer("Frase enviada ✅")
            await q.edit_message_text(admin_private_block_text(chat_id, "daily_phrase"), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, "daily_phrase"))
            return
    await _old_admin_private_config_callback_v30(update, context)



# =========================
# PATCH V31: Pregonero recurrente configurable por perfil + salidas voluntarias
# =========================

def _v31_pregonero_job(chat_id: int, jid: int) -> Optional[Dict[str, Any]]:
    for job in pregonero_auto_jobs(chat_id):
        try:
            if int(job.get("id", 0) or 0) == int(jid):
                return job
        except Exception:
            continue
    return None


def _v31_job_profile(job: Dict[str, Any], chat_id: int) -> Dict[str, Any]:
    profile = job.get("profile") if isinstance(job.get("profile"), dict) else None
    if not profile:
        profile = {
            "text": cfg_value(chat_id, "pregonero_text", "📣 <b>EL PLAN TE LLAMA</b>\n\n{mentions}"),
            "media": cfg_value(chat_id, "pregonero_media", None),
            "buttons": cfg_value(chat_id, "pregonero_buttons", []),
            "media_position": cfg_value(chat_id, "pregonero_media_position", "above"),
        }
        job["profile"] = profile
    profile.setdefault("text", "📣 <b>EL PLAN TE LLAMA</b>\n\n{mentions}")
    profile.setdefault("media", None)
    profile.setdefault("buttons", [])
    profile.setdefault("media_position", profile.get("position", "above"))
    return profile


def _v31_schedule_time_matches(schedule: Dict[str, Any], now_ts: int) -> bool:
    """Solo dispara en el minuto exacto configurado, nunca antes ni después."""
    d = _v30_local_dt(now_ts) if "_v30_local_dt" in globals() else _local_dt_v15(now_ts)
    stype = str((schedule or {}).get("type") or "daily")
    try:
        hh, mm = [int(x) for x in str((schedule or {}).get("time", "21:00")).split(":", 1)]
    except Exception:
        return False
    if (d.hour, d.minute) != (hh, mm):
        return False
    if stype == "weekly":
        days = schedule.get("days") if isinstance(schedule.get("days"), list) else []
        try:
            return d.weekday() in [int(x) for x in days]
        except Exception:
            return False
    if stype == "date":
        return d.strftime("%Y-%m-%d") == str(schedule.get("date", ""))
    return True


# Sobrescribimos due para que el pregonero no salga antes/después: solo minuto exacto.
def pregonero_auto_due(cfg: Dict[str, Any], now_ts: int) -> bool:
    if not bool(cfg.get("pregonero_auto_enabled", cfg.get("enabled", True))):
        return False
    sched = cfg.get("pregonero_auto_schedule") if isinstance(cfg.get("pregonero_auto_schedule"), dict) else cfg.get("schedule") if isinstance(cfg.get("schedule"), dict) else None
    if not sched:
        sched = {"type": "daily", "time": str(cfg.get("pregonero_auto_time", "21:00")), "label": f"diario {cfg.get('pregonero_auto_time', '21:00')}"}
    if not _v31_schedule_time_matches(sched, now_ts):
        return False
    due_key = _v30_schedule_key(sched, now_ts) if "_v30_schedule_key" in globals() else str(int(now_ts // 60))
    return cfg.get("pregonero_auto_last_key") != due_key and cfg.get("pregonero_auto_last_day") != due_key


def _v31_pregonero_job_text(chat_id: int, jid: int) -> str:
    job = _v31_pregonero_job(chat_id, jid)
    if not job:
        return "No encuentro ese pregonero automático."
    profile = _v31_job_profile(job, chat_id)
    sched = job.get("pregonero_auto_schedule") if isinstance(job.get("pregonero_auto_schedule"), dict) else {}
    status = "ON" if bool(job.get("pregonero_auto_enabled", job.get("enabled", True))) else "OFF"
    media = "sí" if isinstance(profile.get("media"), dict) and profile.get("media", {}).get("file_id") else "no"
    buttons = profile.get("buttons") if isinstance(profile.get("buttons"), list) else []
    last_key = str(job.get("pregonero_auto_last_key") or "—")
    return (
        f"<b>📣 Pregonero automático #{jid}</b>\n\n"
        f"Nombre: <b>{h(job.get('name') or job.get('label') or sched.get('label') or f'Auto #{jid}')}</b>\n"
        f"Estado: <b>{status}</b>\n"
        f"Horario: <b>{h(sched.get('label') or job.get('label') or '')}</b>\n"
        f"Último envío: <b>{h(last_key)}</b>\n"
        f"Multimedia: <b>{media}</b> · Botones: <b>{len(buttons)}</b>\n\n"
        f"<b>Texto:</b>\n{profile.get('text', '')}\n\n"
        f"<i>Variables: {{mentions}}, {{count}}, {{total}}</i>"
    )


def _v31_pregonero_job_markup(chat_id: int, jid: int) -> InlineKeyboardMarkup:
    job = _v31_pregonero_job(chat_id, jid) or {}
    enabled = bool(job.get("pregonero_auto_enabled", job.get("enabled", True)))
    rows = [
        [InlineKeyboardButton("👁 Vista previa", callback_data=f"cfg|pauto_preview|{chat_id}|{jid}|pregonero")],
        [InlineKeyboardButton("✏️ Nombre", callback_data=f"cfg|pauto_name|{chat_id}|{jid}|pregonero"),
         InlineKeyboardButton("✏️ Texto", callback_data=f"cfg|pauto_text|{chat_id}|{jid}|pregonero")],
        [InlineKeyboardButton("🖼 Multimedia", callback_data=f"cfg|pauto_media|{chat_id}|{jid}|pregonero"),
         InlineKeyboardButton("⌨️ Botones", callback_data=f"cfg|pauto_buttons|{chat_id}|{jid}|pregonero")],
        [InlineKeyboardButton("⏰ Horario", callback_data=f"cfg|pauto_schedule|{chat_id}|{jid}|pregonero"),
         InlineKeyboardButton(("🟢 ON" if enabled else "⚫ OFF"), callback_data=f"cfg|pauto_toggle|{chat_id}|{jid}|pregonero")],
        [InlineKeyboardButton("🚀 Lanzar este", callback_data=f"cfg|pauto_send|{chat_id}|{jid}|pregonero"),
         InlineKeyboardButton("🗑 Borrar", callback_data=f"cfg|pauto_delete|{chat_id}|{jid}|pregonero")],
        [InlineKeyboardButton("🔙 Volver a pregoneros", callback_data=f"cfg|block|{chat_id}|pregonero")],
    ]
    return InlineKeyboardMarkup(rows)


def _v31_profile_buttons_markup_from_list(buttons: Any) -> Optional[InlineKeyboardMarkup]:
    if not isinstance(buttons, list) or not buttons:
        return None
    rows: List[List[InlineKeyboardButton]] = []
    for btn in buttons[:12]:
        if not isinstance(btn, dict):
            continue
        text = str(btn.get("text", "")).strip()
        url = str(btn.get("url", "")).strip()
        if text and url:
            rows.append([InlineKeyboardButton(text, url=url)])
    return InlineKeyboardMarkup(rows) if rows else None


async def _v31_send_profile_data_message(bot, chat_id: int, profile: Dict[str, Any], text: str) -> Optional[int]:
    media = profile.get("media") if isinstance(profile.get("media"), dict) else None
    markup = _v31_profile_buttons_markup_from_list(profile.get("buttons"))
    position = str(profile.get("media_position") or profile.get("position") or "above")
    has_media = isinstance(media, dict) and media.get("file_id")
    if has_media and position == "above":
        await send_media_blob(bot, chat_id, media)
        msg = await bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
        return getattr(msg, "message_id", None)
    if has_media and position == "below":
        msg = await bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
        await send_media_blob(bot, chat_id, media)
        return getattr(msg, "message_id", None)
    if has_media:
        sent_id = await send_media_blob(bot, chat_id, media, caption=text, reply_markup=markup)
        if sent_id:
            return sent_id
    msg = await bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
    return getattr(msg, "message_id", None)


async def _v31_send_pregonero_job_preview(bot, private_chat_id: int, chat_id: int, jid: int) -> None:
    job = _v31_pregonero_job(chat_id, jid)
    if not job:
        await bot.send_message(private_chat_id, "No encuentro ese pregonero automático.")
        return
    profile = _v31_job_profile(job, chat_id)
    text = str(profile.get("text") or "📣 <b>EL PLAN TE LLAMA</b>\n\n{mentions}")
    text = text.replace("{mentions}", "@usuario1 @usuario2 @usuario3 @usuario4").replace("{count}", "4").replace("{total}", "28")
    await bot.send_message(private_chat_id, f"👁 <b>Vista previa pregonero #{jid}</b>\n<i>Así se verá con multimedia y botones.</i>", parse_mode=ParseMode.HTML)
    await _v31_send_profile_data_message(bot, private_chat_id, profile, text)


# Usuarios que se fueron voluntariamente / no expulsados.
def _v31_left_users(chat_id: int) -> List[Dict[str, Any]]:
    cfg = admin_cfg(chat_id)
    data = cfg.setdefault("left_users", [])
    if not isinstance(data, list):
        data = []
        cfg["left_users"] = data
    return data


def _v31_record_left_user(chat_id: int, user, *, source: str = "left") -> None:
    try:
        uid = int(getattr(user, "id", 0) or 0)
    except Exception:
        uid = 0
    if not uid:
        return
    now = int(time.time())
    data = _v31_left_users(chat_id)
    # Evita duplicados recientes.
    for row in data:
        try:
            if int(row.get("user_id", 0) or 0) == uid and now - int(row.get("ts", 0) or 0) < 300:
                return
        except Exception:
            continue
    rec = {
        "user_id": uid,
        "name": display_name(user),
        "username": getattr(user, "username", "") or "",
        "ts": now,
        "source": source,
    }
    data.insert(0, rec)
    del data[200:]
    save_all_states()


def admin_left_users_text(chat_id: int) -> str:
    data = _v31_left_users(chat_id)
    if not data:
        return "<b>🚶 Usuarios que se fueron</b>\n\nNo hay salidas voluntarias registradas todavía."
    lines = ["<b>🚶 Usuarios que se fueron</b>", "<i>No incluye expulsados detectados como kicked.</i>", ""]
    for row in data[:50]:
        name = h(row.get("name") or row.get("username") or row.get("user_id"))
        uid = h(row.get("user_id", ""))
        ts = int(row.get("ts", 0) or 0)
        when = time.strftime("%d/%m %H:%M", time.localtime(ts)) if ts else "—"
        username = f" @{h(row.get('username'))}" if row.get("username") else ""
        lines.append(f"• <b>{name}</b>{username} · <code>{uid}</code> · {h(when)}")
    return "\n".join(lines)


