async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ""
    if q and data.startswith("cfg|"):
        parts = data.split("|")
        action = parts[1] if len(parts) > 1 else ""
        try:
            chat_id = int(parts[2]) if len(parts) > 2 and parts[2].lstrip('-').isdigit() else 0
        except Exception:
            chat_id = 0
        # Listado de usuarios que se fueron.
        if action == "leftusers":
            await q.edit_message_text(admin_left_users_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=cfg_back_markup(chat_id, "lists"))
            return
        # Ficha de cada pregonero automático.
        if action.startswith("pauto_") and len(parts) >= 4:
            try:
                jid = int(parts[3])
            except Exception:
                jid = 0
            job = _v31_pregonero_job(chat_id, jid)
            if action != "pauto_edit" and not job:
                await q.answer("No encuentro ese pregonero.", show_alert=True)
                await q.edit_message_text(admin_private_block_text(chat_id, "pregonero"), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, "pregonero"))
                return
            if action == "pauto_edit":
                if not job:
                    await q.answer("No encuentro ese pregonero.", show_alert=True)
                    return
                await q.edit_message_text(_v31_pregonero_job_text(chat_id, jid), parse_mode=ParseMode.HTML, reply_markup=_v31_pregonero_job_markup(chat_id, jid))
                return
            if action == "pauto_preview":
                await _v31_send_pregonero_job_preview(context.bot, q.message.chat.id, chat_id, jid)
                await q.answer("Vista previa enviada ✅")
                return
            if action == "pauto_toggle":
                job["pregonero_auto_enabled"] = not bool(job.get("pregonero_auto_enabled", job.get("enabled", True)))
                save_all_states()
                await q.answer("Auto ON/OFF actualizado ✅")
                await q.edit_message_text(_v31_pregonero_job_text(chat_id, jid), parse_mode=ParseMode.HTML, reply_markup=_v31_pregonero_job_markup(chat_id, jid))
                return
            if action == "pauto_delete":
                jobs = pregonero_auto_jobs(chat_id)
                if job in jobs:
                    jobs.remove(job)
                    save_all_states()
                await q.answer("Pregonero automático borrado ✅")
                await q.edit_message_text(admin_private_block_text(chat_id, "pregonero"), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, "pregonero"))
                return
            if action == "pauto_send":
                await q.answer("Lanzando este pregonero…")
                await send_pregonero(context, chat_id, job=job)
                await q.edit_message_text(_v31_pregonero_job_text(chat_id, jid), parse_mode=ParseMode.HTML, reply_markup=_v31_pregonero_job_markup(chat_id, jid))
                return
            if action in ("pauto_name", "pauto_text", "pauto_buttons", "pauto_media", "pauto_schedule"):
                kind_map = {
                    "pauto_name": "cfg_pregonero_job_name",
                    "pauto_text": "cfg_pregonero_job_text",
                    "pauto_buttons": "cfg_pregonero_job_buttons",
                    "pauto_media": "cfg_pregonero_job_media",
                    "pauto_schedule": "cfg_pregonero_job_schedule",
                }
                set_config_pending(update.effective_user.id, {"kind": kind_map[action], "chat_id": chat_id, "jid": jid, "return_block": "pregonero"})
                if action == "pauto_media":
                    prompt = "🖼 <b>Multimedia del pregonero</b>\n\nEnvíame foto, vídeo, GIF o documento.\nPara quitarla escribe <code>QUITAR</code>."
                elif action == "pauto_buttons":
                    prompt = "⌨️ <b>Botones del pregonero</b>\n\nFormato:\n<code>Texto - https://enlace.com</code>\n<code>Canal=https://t.me/...</code>\n\nPara borrar todos escribe <code>QUITAR</code>."
                elif action == "pauto_schedule":
                    prompt = "⏰ <b>Horario de este pregonero</b>\n\nEjemplos:\n<code>21:30</code>\n<code>lunes 21:30</code>\n<code>lunes,miercoles,viernes 21:30</code>\n<code>2026-05-15 21:30</code>"
                elif action == "pauto_name":
                    prompt = "✏️ <b>Nombre interno del pregonero</b>\n\nEjemplo: <code>Pregonero mañana</code>"
                else:
                    prompt = "✏️ <b>Texto de este pregonero</b>\n\nUsa <code>{mentions}</code> donde quieras que aparezcan los usuarios.\nTambién: <code>{count}</code>, <code>{total}</code>."
                await q.edit_message_text(prompt, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("❌ Cancelar", callback_data=f"cfg|pauto_edit|{chat_id}|{jid}|pregonero")]]))
                return
        # Mantener compatibilidad con los botones viejos de borrar/toggle.
        if action in ("pregonero_auto_toggle", "pregonero_auto_del") and len(parts) >= 4:
            try:
                jid = int(parts[3])
            except Exception:
                jid = 0
            if action == "pregonero_auto_toggle":
                action = "pauto_toggle"
            else:
                action = "pauto_delete"
    await _old_admin_private_config_callback_v31(update, context)


async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.effective_user or not update.message or update.effective_chat.type != "private":
        return await _old_admin_private_config_text_v31(update, context)
    pending = get_config_pending(update.effective_user.id)
    if not pending:
        return await _old_admin_private_config_text_v31(update, context)
    kind = str(pending.get("kind") or "")
    if not kind.startswith("cfg_pregonero_job_"):
        return await _old_admin_private_config_text_v31(update, context)
    if not is_global_admin_user(update.effective_user.id):
        return True
    chat_id = int(pending.get("chat_id", 0) or 0)
    jid = int(pending.get("jid", 0) or 0)
    job = _v31_pregonero_job(chat_id, jid)
    if not job:
        pop_config_pending(update.effective_user.id)
        await update.message.reply_html("No encuentro ese pregonero.", reply_markup=admin_private_block_markup(chat_id, "pregonero"))
        return True
    text = plain_text_from_message(update.message).strip()
    html_text = telegram_html_from_message(update.message).strip()
    profile = _v31_job_profile(job, chat_id)
    if kind == "cfg_pregonero_job_name":
        job["name"] = text[:80] or f"Pregonero #{jid}"
    elif kind == "cfg_pregonero_job_text":
        profile["text"] = html_text or h(text)
    elif kind == "cfg_pregonero_job_buttons":
        if text.upper() == "QUITAR":
            profile["buttons"] = []
        else:
            buttons = parse_buttons_text(text)
            if not buttons:
                await update.message.reply_html("No he detectado botones válidos. Usa: <code>Texto - https://enlace.com</code>")
                return True
            profile["buttons"] = buttons
    elif kind == "cfg_pregonero_job_media":
        if text.upper() == "QUITAR":
            profile["media"] = None
        else:
            await update.message.reply_html("Envíame una foto, vídeo, GIF o documento; o escribe <code>QUITAR</code>.")
            return True
    elif kind == "cfg_pregonero_job_schedule":
        try:
            sched = parse_pregonero_auto_schedule(text)
        except ValueError as e:
            await update.message.reply_html(h(str(e)))
            return True
        job["pregonero_auto_schedule"] = sched
        job["pregonero_auto_time"] = sched.get("time", "21:00")
        job["label"] = sched.get("label", "")
        job["pregonero_auto_last_key"] = ""
        job["pregonero_auto_last_day"] = ""
    save_all_states()
    pop_config_pending(update.effective_user.id)
    await update.message.reply_html("✅ Pregonero actualizado.\n\n" + _v31_pregonero_job_text(chat_id, jid), reply_markup=_v31_pregonero_job_markup(chat_id, jid))
    return True


async def admin_private_config_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message or not update.effective_chat or update.effective_chat.type != "private":
        return await _old_admin_private_config_media_v31(update, context)
    pending = get_config_pending(update.effective_user.id)
    if not pending or str(pending.get("kind") or "") != "cfg_pregonero_job_media":
        return await _old_admin_private_config_media_v31(update, context)
    if not is_global_admin_user(update.effective_user.id):
        return
    chat_id = int(pending.get("chat_id", 0) or 0)
    jid = int(pending.get("jid", 0) or 0)
    job = _v31_pregonero_job(chat_id, jid)
    if not job:
        pop_config_pending(update.effective_user.id)
        await update.message.reply_html("No encuentro ese pregonero.", reply_markup=admin_private_block_markup(chat_id, "pregonero"))
        return
    media: Optional[Dict[str, str]] = None
    if update.message.photo:
        media = {"type": "photo", "file_id": update.message.photo[-1].file_id}
    elif update.message.video:
        media = {"type": "video", "file_id": update.message.video.file_id}
    elif update.message.animation:
        media = {"type": "animation", "file_id": update.message.animation.file_id}
    elif update.message.document:
        media = {"type": "document", "file_id": update.message.document.file_id}
    if not media:
        await update.message.reply_text("Ese tipo de archivo no está soportado. Envía foto, vídeo, GIF o documento.")
        return
    profile = _v31_job_profile(job, chat_id)
    profile["media"] = media
    if update.message.caption:
        profile["text"] = telegram_html_from_message(update.message, caption=True).strip() or profile.get("text", "")
    save_all_states()
    pop_config_pending(update.effective_user.id)
    await update.message.reply_html("✅ Multimedia del pregonero actualizada.\n\n" + _v31_pregonero_job_text(chat_id, jid), reply_markup=_v31_pregonero_job_markup(chat_id, jid))


async def validation_chat_member_update(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    # Registrar salidas voluntarias antes de ejecutar la lógica original.
    try:
        cmu = update.chat_member
        chat_id = int(cmu.chat.id)
        old_status = str(getattr(cmu.old_chat_member, "status", "") or "")
        new_status = str(getattr(cmu.new_chat_member, "status", "") or "")
        user = cmu.new_chat_member.user
        # Telegram suele marcar salida voluntaria como left; expulsión como kicked.
        if old_status not in ("left", "kicked", "") and new_status == "left":
            _v31_record_left_user(chat_id, user, source="left")
    except Exception:
        logger.exception("No se pudo registrar usuario que salió")
    await _old_validation_chat_member_update_v31(update, context)




