def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    if block == "polls":
        polls = _v32_polls(chat_id)
        open_count = sum(1 for p in polls if str(p.get("status") or "open") == "open")
        lines = [
            "<b>📊 Encuestas anónimas</b>",
            "",
            "Crea encuestas con botones propios del bot.",
            "Los votos son anónimos y los porcentajes solo aparecen al finalizar.",
            "",
            f"Abiertas: <b>{open_count}</b> · Total guardadas: <b>{len(polls)}</b>",
            "",
            "Formato rápido:",
            "<code>Pregunta | Opción 1 | Opción 2 | 30m</code>",
            "<code>multi | Pregunta | Opción 1 | Opción 2 | 1h</code>",
        ]
        if polls:
            lines.extend(["", "<b>Últimas:</b>"])
            for p in polls[:8]:
                status = "🟢" if str(p.get("status") or "open") == "open" else "⚫"
                lines.append(f"{status} #{int(p.get('id',0) or 0)} · {h(str(p.get('question',''))[:55])}")
        return "\n".join(lines)
    return _old_admin_private_block_text_v32(chat_id, block, page)


def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    if block == "polls":
        rows: List[List[InlineKeyboardButton]] = [
            [InlineKeyboardButton("➕ Nueva encuesta", callback_data=f"cfg|poll_new|{chat_id}|polls")],
        ]
        for p in _v32_polls(chat_id)[:8]:
            pid = int(p.get("id", 0) or 0)
            status = "🟢" if str(p.get("status") or "open") == "open" else "⚫"
            title = str(p.get("question") or "Encuesta")[:30]
            rows.append([InlineKeyboardButton(f"{status} #{pid} {title}", callback_data=f"cfg|poll_view|{chat_id}|{pid}|polls")])
            if str(p.get("status") or "open") == "open":
                rows.append([InlineKeyboardButton("✅ Finalizar", callback_data=f"cfg|poll_close|{chat_id}|{pid}|polls")])
        rows.extend(block_footer_rows(chat_id, block))
        return InlineKeyboardMarkup(rows)
    return _old_admin_private_block_markup_v32(chat_id, block, page)


async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ""
    if q and data.startswith("cfg|"):
        parts = data.split("|")
        action = parts[1] if len(parts) > 1 else ""
        try:
            chat_id = int(parts[2]) if len(parts) > 2 and parts[2].lstrip('-').isdigit() else 0
        except Exception:
            chat_id = 0
        if action == "poll_new":
            set_config_pending(q.from_user.id, {"kind": "cfg_poll_new", "chat_id": chat_id})
            await q.edit_message_text(
                "📊 <b>Nueva encuesta anónima</b>\n\n"
                "Envíame:\n<code>Pregunta | Opción 1 | Opción 2 | 30m</code>\n\n"
                "Para varias respuestas:\n<code>multi | Pregunta | Opción 1 | Opción 2 | 1h</code>\n\n"
                "Máximo 10 opciones. Los resultados se enseñan al finalizar.",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("❌ Cancelar", callback_data=f"cfg|block|{chat_id}|polls")]])
            )
            return
        if action == "poll_view" and len(parts) >= 4:
            pid = int(parts[3])
            poll = _v32_poll_find(chat_id, pid)
            if not poll:
                await q.answer("No encuentro esa encuesta", show_alert=True)
                return
            await q.edit_message_text(_v32_poll_text(poll, results=str(poll.get("status")) != "open"), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, "polls"))
            return
        if action == "poll_close" and len(parts) >= 4:
            pid = int(parts[3])
            poll = _v32_poll_find(chat_id, pid)
            if not poll:
                await q.answer("No encuentro esa encuesta", show_alert=True)
                return
            await _v32_close_poll(context, chat_id, poll, silent=True)
            await q.answer("Encuesta finalizada ✅")
            await q.edit_message_text(admin_private_block_text(chat_id, "polls"), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, "polls"))
            return
    await _old_admin_private_config_callback_v32(update, context)


async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.effective_user or not update.message or update.effective_chat.type != "private":
        return await _old_admin_private_config_text_v32(update, context)
    pending = get_config_pending(update.effective_user.id)
    if not pending or str(pending.get("kind") or "") != "cfg_poll_new":
        return await _old_admin_private_config_text_v32(update, context)
    if not is_global_admin_user(update.effective_user.id):
        return True
    chat_id = int(pending.get("chat_id", 0) or 0)
    text = plain_text_from_message(update.message).strip()
    try:
        question, options, close_seconds, multi = _v32_parse_poll_spec(text)
    except ValueError as e:
        await update.message.reply_html(f"⚠️ {h(str(e))}")
        return True
    poll = await _v32_create_poll(context, chat_id, question, options, close_seconds, multi, update.effective_user.id)
    pop_config_pending(update.effective_user.id)
    await update.message.reply_html(
        f"✅ Encuesta creada en el grupo.\nID: <b>#{int(poll.get('id'))}</b> · Cierra en <b>{h(_v32_duration_label(close_seconds))}</b>",
        reply_markup=admin_private_block_markup(chat_id, "polls")
    )
    return True


async def callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if q and (q.data or "").startswith("poll|"):
        await poll_callback_router(update, context)
        return
    await _old_callback_router_v32(update, context)


async def on_startup(application: Application) -> None:
    global POLL_TASK
    await _old_on_startup_v32(application)
    try:
        if application.job_queue:
            application.job_queue.run_repeating(poll_close_loop, interval=20, first=10, name="poll_close_loop")
    except Exception:
        logger.exception("No se pudo iniciar job_queue de encuestas")


async def on_shutdown(application: Application) -> None:
    await _old_on_shutdown_v32(application)


def build_application() -> Application:
    app = _old_build_application_v32()
    # Añadimos comandos específicos. El router genérico ya intercepta callbacks poll|.
    app.add_handler(command_handler("encuesta", encuesta_command))
    app.add_handler(command_handler("encuestas", encuestas_command))
    return app




# =========================
# PATCH V33: Encuestas avanzadas + avisos privados + ping de estado
# =========================

POLL_MAX_SECONDS_V33 = 7 * 24 * 3600
POLL_DEFAULT_SECONDS_V33 = 3600


def _v33_now_ts() -> int:
    import time as _time
    return int(_time.time())


def _v33_owner_ids_env() -> set[int]:
    raw = os.getenv("BOT_OWNER_IDS", "").strip()
    ids = parse_admin_ids(raw) if raw else set()
    if not ids:
        ids = set(ADMIN_IDS)
    return {int(x) for x in ids if int(x) > 0}


def _v33_poll_buttons_to_markup(buttons: Any, *, extra_rows: Optional[List[List[InlineKeyboardButton]]] = None) -> Optional[InlineKeyboardMarkup]:
    rows: List[List[InlineKeyboardButton]] = []
    if isinstance(buttons, list):
        row: List[InlineKeyboardButton] = []
        for b in buttons[:20]:
            if not isinstance(b, dict):
                continue
            text = str(b.get("text") or b.get("label") or "Botón")[:64]
            url = str(b.get("url") or "").strip()
            if not url:
                continue
            row.append(InlineKeyboardButton(text, url=url))
            if len(row) == 2:
                rows.append(row); row = []
        if row:
            rows.append(row)
    if extra_rows:
        rows.extend(extra_rows)
    return InlineKeyboardMarkup(rows) if rows else None


def _v33_extract_media_from_message(message) -> Optional[Dict[str, str]]:
    try:
        if getattr(message, "photo", None):
            return {"type": "photo", "file_id": message.photo[-1].file_id}
        if getattr(message, "video", None):
            return {"type": "video", "file_id": message.video.file_id}
        if getattr(message, "animation", None):
            return {"type": "animation", "file_id": message.animation.file_id}
        if getattr(message, "document", None):
            return {"type": "document", "file_id": message.document.file_id}
    except Exception:
        return None
    return None


def _v33_parse_duration_seconds(value: str, default: int = POLL_DEFAULT_SECONDS_V33) -> int:
    raw = (value or "").strip().lower().replace(" ", "")
    if not raw:
        return default
    try:
        if raw.endswith("s"):
            sec = int(raw[:-1])
        elif raw.endswith("m"):
            sec = int(raw[:-1]) * 60
        elif raw.endswith("h"):
            sec = int(raw[:-1]) * 3600
        elif raw.endswith("d"):
            sec = int(raw[:-1]) * 86400
        elif raw.endswith("sem") or raw.endswith("semana") or raw.endswith("semanas"):
            num = raw.split("sem", 1)[0] or "1"
            sec = int(num) * 7 * 86400
        else:
            sec = int(raw) * 60
        return max(60, min(POLL_MAX_SECONDS_V33, sec))
    except Exception:
        return default


def _v33_duration_label(seconds: int) -> str:
    try:
        seconds = max(0, int(seconds))
    except Exception:
        seconds = 0
    if seconds >= 86400 and seconds % 86400 == 0:
        n = seconds // 86400
        if n == 7:
            return "1 semana"
        return f"{n} día" if n == 1 else f"{n} días"
    if seconds >= 3600 and seconds % 3600 == 0:
        n = seconds // 3600
        return f"{n} hora" if n == 1 else f"{n} horas"
    if seconds >= 60 and seconds % 60 == 0:
        n = seconds // 60
        return f"{n} minuto" if n == 1 else f"{n} minutos"
    return f"{seconds} segundos"


def _v32_duration_label(seconds: int) -> str:  # type: ignore[override]
    return _v33_duration_label(seconds)


def _v32_parse_duration_seconds(value: str, default: int = 3600) -> int:  # type: ignore[override]
    return _v33_parse_duration_seconds(value, default)


def _v33_poll_total_votes(poll: Dict[str, Any]) -> int:
    votes = poll.get("votes") if isinstance(poll.get("votes"), dict) else {}
    return len(votes)


def _v33_poll_is_open(poll: Dict[str, Any]) -> bool:
    return str(poll.get("status") or "open") == "open"


def _v32_poll_text(poll: Dict[str, Any], *, results: bool = False) -> str:  # type: ignore[override]
    q = h(poll.get("question", "Encuesta"))
    desc = str(poll.get("description") or "").strip()
    multi = bool(poll.get("multi", False))
    status = str(poll.get("status") or "open")
    close_ts = int(poll.get("close_ts", 0) or 0)
    now = _v33_now_ts()
    remaining = max(0, close_ts - now) if close_ts else 0
    title = "📊 <b>Encuesta anónima</b>" if status != "draft" else "📝 <b>Borrador de encuesta</b>"
    lines = [title, "", f"<b>{q}</b>"]
    if desc:
        lines.extend(["", h(desc)])
    lines.append("")
    lines.append("Tipo: <b>varias respuestas</b>" if multi else "Tipo: <b>una respuesta</b>")
    if status == "draft":
        lines.append("Estado: <b>borrador</b>")
    elif status == "open":
        lines.append(f"Estado: <b>abierta</b> · queda <b>{h(_v33_duration_label(remaining))}</b>")
        lines.append(f"Votos recibidos: <b>{_v33_poll_total_votes(poll)}</b>")
        lines.append("<i>Los porcentajes se mostrarán solo al finalizar.</i>")
    else:
        lines.append("Estado: <b>finalizada</b>")
    if results or status == "closed":
        opts = poll.get("options") if isinstance(poll.get("options"), list) else []
        counts = _v32_poll_counts(poll)
        total = sum(counts)
        lines.extend(["", "<b>Resultados finales:</b>"])
        for idx, opt in enumerate(opts):
            c = counts[idx] if idx < len(counts) else 0
            pct = int(round((c / total) * 100)) if total else 0
            bar = "█" * max(1, min(10, pct // 10)) if c else "░"
            lines.append(f"{idx+1}. {h(opt)} — <b>{c}</b> votos · <b>{pct}%</b> {bar}")
        lines.append(f"\nTotal votos: <b>{total}</b>")
    else:
        opts = poll.get("options") if isinstance(poll.get("options"), list) else []
        lines.extend(["", "<b>Opciones:</b>"])
        for idx, opt in enumerate(opts):
            lines.append(f"{idx+1}. {h(opt)}")
    return "\n".join(lines)


def _v32_poll_markup(chat_id: int, poll: Dict[str, Any]) -> Optional[InlineKeyboardMarkup]:  # type: ignore[override]
    if str(poll.get("status") or "open") != "open":
        return None
    poll_id = int(poll.get("id", 0) or 0)
    opts = poll.get("options") if isinstance(poll.get("options"), list) else []
    rows: List[List[InlineKeyboardButton]] = []
    for idx, opt in enumerate(opts):
        rows.append([InlineKeyboardButton(f"{idx+1}. {str(opt)[:48]}", callback_data=f"poll|vote|{chat_id}|{poll_id}|{idx}")])
    rows.append([InlineKeyboardButton("✅ Terminar encuesta", callback_data=f"poll|close|{chat_id}|{poll_id}")])
    return _v33_poll_buttons_to_markup(poll.get("buttons"), extra_rows=rows)


async def _v33_send_or_edit_poll_message(context: ContextTypes.DEFAULT_TYPE, chat_id: int, poll: Dict[str, Any]) -> Optional[int]:
    text = _v32_poll_text(poll, results=False)
    markup = _v32_poll_markup(chat_id, poll)
    media = poll.get("media") if isinstance(poll.get("media"), dict) else None
    msg_id = int(poll.get("message_id", 0) or 0)
    if msg_id:
        try:
            if media and media.get("file_id"):
                await context.bot.edit_message_caption(chat_id=chat_id, message_id=msg_id, caption=text, parse_mode=ParseMode.HTML, reply_markup=markup)
            else:
                await context.bot.edit_message_text(chat_id=chat_id, message_id=msg_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
            return msg_id
        except Exception:
            logger.exception("No se pudo editar encuesta; se intentará recrear")
    if media and media.get("file_id"):
        sent_id = await send_media_blob(context.bot, chat_id, media, caption=text, reply_markup=markup)
        if sent_id:
            poll["message_id"] = sent_id
            return sent_id
    else:
        msg = await context.bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
        poll["message_id"] = msg.message_id
        return msg.message_id
    return None


async def _v33_pin_poll_notice(context: ContextTypes.DEFAULT_TYPE, chat_id: int, poll: Dict[str, Any]) -> None:
    if not bool(poll.get("pin_notice", False)):
        return
    msg_id = int(poll.get("message_id", 0) or 0)
    if not msg_id:
        return
    try:
        link = _message_link_v20(chat_id, msg_id) if "_message_link_v20" in globals() else ""
    except Exception:
        link = ""
    if not link:
        return
    title = str(poll.get("pin_title") or poll.get("question") or "Encuesta")[:80]
    old = int(poll.get("pin_message_id", 0) or 0)
    if old:
        try:
            await context.bot.delete_message(chat_id, old)
        except Exception:
            pass
    msg = await context.bot.send_message(
        chat_id,
        f"📌 <b>{h(title)}</b>\n\nPulsa para votar en la encuesta.",
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🗳 Votar", url=link)]])
    )
    poll["pin_message_id"] = msg.message_id
    try:
        await context.bot.pin_chat_message(chat_id=chat_id, message_id=msg.message_id, disable_notification=True)
    except Exception:
        pass
    save_all_states()


async def _v32_create_poll(context: ContextTypes.DEFAULT_TYPE, chat_id: int, question: str, options: List[str], close_seconds: int, multi: bool, creator_id: int = 0) -> Dict[str, Any]:  # type: ignore[override]
    poll_id = _v32_next_poll_id(chat_id)
    now = _v33_now_ts()
    close_seconds = _v33_parse_duration_seconds(str(close_seconds), POLL_DEFAULT_SECONDS_V33) if isinstance(close_seconds, str) else max(60, min(POLL_MAX_SECONDS_V33, int(close_seconds)))
    poll = {
        "id": poll_id,
        "question": question[:250],
        "description": "",
        "options": [str(o)[:90] for o in options[:10]],
        "multi": bool(multi),
        "anonymous": True,
        "status": "open",
        "creator_id": int(creator_id or 0),
        "created_ts": now,
        "duration_seconds": int(close_seconds),
        "close_ts": now + int(close_seconds),
        "message_id": 0,
        "votes": {},
        "media": None,
        "buttons": [],
        "pin_notice": False,
        "repeat_enabled": False,
        "repeat_seconds": 0,
        "next_repeat_ts": 0,
    }
    await _v33_send_or_edit_poll_message(context, chat_id, poll)
    _v32_polls(chat_id).insert(0, poll)
    await _v33_pin_poll_notice(context, chat_id, poll)
    save_all_states()
    return poll


async def _v33_launch_poll(context: ContextTypes.DEFAULT_TYPE, chat_id: int, poll: Dict[str, Any]) -> None:
    now = _v33_now_ts()
    poll["status"] = "open"
    poll["created_ts"] = now
    poll["duration_seconds"] = int(poll.get("duration_seconds", POLL_DEFAULT_SECONDS_V33) or POLL_DEFAULT_SECONDS_V33)
    poll["close_ts"] = now + int(poll["duration_seconds"])
    poll["votes"] = {}
    poll["message_id"] = 0
    await _v33_send_or_edit_poll_message(context, chat_id, poll)
    await _v33_pin_poll_notice(context, chat_id, poll)
    save_all_states()


async def _v32_close_poll(context: ContextTypes.DEFAULT_TYPE, chat_id: int, poll: Dict[str, Any], *, silent: bool = False) -> None:  # type: ignore[override]
    if str(poll.get("status") or "open") != "open":
        return
    poll["status"] = "closed"
    poll["closed_ts"] = _v33_now_ts()
    if bool(poll.get("repeat_enabled")):
        rep = int(poll.get("repeat_seconds", 0) or 0)
        if rep > 0:
            poll["next_repeat_ts"] = _v33_now_ts() + rep
    save_all_states()
    msg_id = int(poll.get("message_id", 0) or 0)
    try:
        media = poll.get("media") if isinstance(poll.get("media"), dict) else None
        if msg_id:
            if media and media.get("file_id"):
                await context.bot.edit_message_caption(chat_id=chat_id, message_id=msg_id, caption=_v32_poll_text(poll, results=True), parse_mode=ParseMode.HTML, reply_markup=None)
            else:
                await context.bot.edit_message_text(chat_id=chat_id, message_id=msg_id, text=_v32_poll_text(poll, results=True), parse_mode=ParseMode.HTML, reply_markup=None)
    except Exception:
        logger.exception("No se pudo cerrar/edit encuesta %s en chat %s", poll.get("id"), chat_id)
    if not silent:
        try:
            await context.bot.send_message(chat_id, f"📊 Encuesta finalizada: <b>{h(poll.get('question',''))}</b>", parse_mode=ParseMode.HTML)
        except Exception:
            pass


async def poll_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    q = update.callback_query
    if not q:
        return
    data = q.data or ""
    parts = data.split("|")
    if len(parts) < 4:
        await q.answer(); return
    action = parts[1]
    try:
        chat_id = int(parts[2]); poll_id = int(parts[3])
    except Exception:
        await q.answer("Encuesta inválida", show_alert=True); return
    poll = _v32_poll_find(chat_id, poll_id)
    if not poll:
        await q.answer("No encuentro esa encuesta", show_alert=True); return
    if action == "vote":
        if not _v33_poll_is_open(poll):
            await q.answer("La encuesta ya terminó", show_alert=True); return
        if _v33_now_ts() >= int(poll.get("close_ts", 0) or 0):
            await _v32_close_poll(context, chat_id, poll, silent=True)
            await q.answer("La encuesta acaba de finalizar", show_alert=True); return
        votes = poll.setdefault("votes", {})
        uid = str(q.from_user.id)
        if uid in votes:
            await q.answer("Ya has votado en esta encuesta ✅", show_alert=True); return
        try:
            opt_idx = int(parts[4])
        except Exception:
            await q.answer("Opción inválida", show_alert=True); return
        opts = poll.get("options") if isinstance(poll.get("options"), list) else []
        if not (0 <= opt_idx < len(opts)):
            await q.answer("Opción inválida", show_alert=True); return
        votes[uid] = opt_idx
        save_all_states()
        await q.answer("Voto guardado ✅")
        try:
            await _v33_send_or_edit_poll_message(context, chat_id, poll)
        except Exception:
            pass
        return
    if action == "close":
        try:
            allowed = int(q.from_user.id) == int(poll.get("creator_id", 0) or 0) or await is_admin(context, chat_id, q.from_user.id)
        except Exception:
            allowed = False
        if not allowed:
            await q.answer("Solo admin o creador puede finalizarla", show_alert=True); return
        await _v32_close_poll(context, chat_id, poll, silent=True)
        await q.answer("Encuesta finalizada ✅")
        return
    await q.answer()


async def poll_close_loop(context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    now = _v33_now_ts()
    for chat_id, state in list(STATE_CACHE.items()):
        try:
            for poll in list(_v32_polls(chat_id)):
                status = str(poll.get("status") or "open")
                if status == "open" and int(poll.get("close_ts", 0) or 0) <= now:
                    await _v32_close_poll(context, chat_id, poll, silent=True)
                elif status == "closed" and bool(poll.get("repeat_enabled")):
                    nxt = int(poll.get("next_repeat_ts", 0) or 0)
                    if nxt and now >= nxt:
                        await _v33_launch_poll(context, chat_id, poll)
        except Exception:
            logger.exception("Error revisando encuestas del chat %s", chat_id)


def _v33_poll_detail_text(chat_id: int, poll: Dict[str, Any]) -> str:
    base = _v32_poll_text(poll, results=str(poll.get("status")) == "closed")
    media = "sí" if isinstance(poll.get("media"), dict) and poll.get("media", {}).get("file_id") else "no"
    buttons = len(poll.get("buttons") or []) if isinstance(poll.get("buttons"), list) else 0
    rep = "OFF"
    if poll.get("repeat_enabled"):
        rep = f"cada {_v33_duration_label(int(poll.get('repeat_seconds',0) or 0))}"
    extra = ["", "<b>Configuración:</b>", f"Multimedia: <b>{media}</b>", f"Botones extra: <b>{buttons}</b>", f"Fijado arriba: <b>{'ON' if poll.get('pin_notice') else 'OFF'}</b>", f"Repetición: <b>{h(rep)}</b>"]
    return base + "\n" + "\n".join(extra)


def _v33_poll_detail_markup(chat_id: int, poll_id: int) -> InlineKeyboardMarkup:
    poll = _v32_poll_find(chat_id, poll_id) or {}
    status = str(poll.get("status") or "draft")
    rows: List[List[InlineKeyboardButton]] = [
        [InlineKeyboardButton("✏️ Pregunta", callback_data=f"cfg|poll_edit_question|{chat_id}|{poll_id}|polls"), InlineKeyboardButton("📝 Descripción", callback_data=f"cfg|poll_edit_desc|{chat_id}|{poll_id}|polls")],
        [InlineKeyboardButton("🔢 Opciones", callback_data=f"cfg|poll_edit_options|{chat_id}|{poll_id}|polls"), InlineKeyboardButton("⏱ Duración", callback_data=f"cfg|poll_edit_duration|{chat_id}|{poll_id}|polls")],
        [InlineKeyboardButton("🖼 Multimedia", callback_data=f"cfg|poll_edit_media|{chat_id}|{poll_id}|polls"), InlineKeyboardButton("⌨️ Botones", callback_data=f"cfg|poll_edit_buttons|{chat_id}|{poll_id}|polls")],
        [InlineKeyboardButton("📌 Fijar aviso ON/OFF", callback_data=f"cfg|poll_toggle_pin|{chat_id}|{poll_id}|polls")],
        [InlineKeyboardButton("🔁 Repetición", callback_data=f"cfg|poll_edit_repeat|{chat_id}|{poll_id}|polls"), InlineKeyboardButton("👁 Vista previa", callback_data=f"cfg|poll_preview|{chat_id}|{poll_id}|polls")],
    ]
    if status == "draft":
        rows.append([InlineKeyboardButton("🚀 Lanzar encuesta", callback_data=f"cfg|poll_launch|{chat_id}|{poll_id}|polls")])
    elif status == "open":
        rows.append([InlineKeyboardButton("✅ Finalizar ahora", callback_data=f"cfg|poll_close|{chat_id}|{poll_id}|polls")])
    rows.append([InlineKeyboardButton("🗑 Borrar", callback_data=f"cfg|poll_delete|{chat_id}|{poll_id}|polls")])
    rows.extend(block_footer_rows(chat_id, "polls"))
    return InlineKeyboardMarkup(rows)


_old_admin_private_block_text_v33 = admin_private_block_text
_old_admin_private_block_markup_v33 = admin_private_block_markup
_old_admin_private_config_callback_v33 = admin_private_config_callback
_old_admin_private_config_text_v33 = admin_private_config_text
_old_admin_private_config_media_v33 = admin_private_config_media
_old_ping_command_v33 = ping_command
_old_build_application_v33 = build_application


def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:  # type: ignore[override]
    if block == "polls":
        polls = _v32_polls(chat_id)
        open_count = sum(1 for p in polls if str(p.get("status") or "open") == "open")
        draft_count = sum(1 for p in polls if str(p.get("status") or "open") == "draft")
        lines = [
            "<b>📊 Encuestas anónimas</b>",
            "",
            "Crea encuestas con pregunta, descripción, multimedia, botones y duración hasta 1 semana.",
            "Los votos son anónimos, solo se puede votar una vez y los porcentajes salen al finalizar.",
            "",
            f"Abiertas: <b>{open_count}</b> · Borradores: <b>{draft_count}</b> · Total: <b>{len(polls)}</b>",
        ]
        if polls:
            lines.extend(["", "<b>Encuestas:</b>"])
            for p in polls[:10]:
                st = str(p.get("status") or "open")
                icon = "🟢" if st == "open" else ("📝" if st == "draft" else "⚫")
                lines.append(f"{icon} #{int(p.get('id',0) or 0)} · {h(str(p.get('question',''))[:55])}")
        return "\n".join(lines)
    return _old_admin_private_block_text_v33(chat_id, block, page)


def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    if block == "polls":
        rows: List[List[InlineKeyboardButton]] = [
            [InlineKeyboardButton("➕ Nueva paso a paso", callback_data=f"cfg|poll_new_wizard|{chat_id}|polls")],
            [InlineKeyboardButton("⚡ Nueva rápida", callback_data=f"cfg|poll_new|{chat_id}|polls")],
        ]
        for p in _v32_polls(chat_id)[:10]:
            pid = int(p.get("id", 0) or 0)
            st = str(p.get("status") or "open")
            icon = "🟢" if st == "open" else ("📝" if st == "draft" else "⚫")
            title = str(p.get("question") or "Encuesta")[:34]
            rows.append([InlineKeyboardButton(f"{icon} #{pid} {title}", callback_data=f"cfg|poll_view|{chat_id}|{pid}|polls")])
        rows.extend(block_footer_rows(chat_id, block))
        return InlineKeyboardMarkup(rows)
    return _old_admin_private_block_markup_v33(chat_id, block, page)


async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    q = update.callback_query
    data = q.data if q else ""
    if q and data.startswith("cfg|"):
        parts = data.split("|")
        action = parts[1] if len(parts) > 1 else ""
        try:
            chat_id = int(parts[2]) if len(parts) > 2 and parts[2].lstrip('-').isdigit() else 0
        except Exception:
            chat_id = 0
        if action == "poll_new_wizard":
            set_config_pending(q.from_user.id, {"kind": "cfg_poll_wizard_question", "chat_id": chat_id, "draft": {}})
            await q.edit_message_text("📊 <b>Nueva encuesta</b>\n\nEnvíame la <b>pregunta</b> de la encuesta.", parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("❌ Cancelar", callback_data=f"cfg|block|{chat_id}|polls")]]))
            return
        if action == "poll_view" and len(parts) >= 4:
            poll = _v32_poll_find(chat_id, int(parts[3]))
            if not poll:
                await q.answer("No encuentro esa encuesta", show_alert=True); return
            await q.edit_message_text(_v33_poll_detail_text(chat_id, poll), parse_mode=ParseMode.HTML, reply_markup=_v33_poll_detail_markup(chat_id, int(poll.get("id",0) or 0)))
            return
        if action.startswith("poll_edit_") and len(parts) >= 4:
            pid = int(parts[3]); poll = _v32_poll_find(chat_id, pid)
            if not poll:
                await q.answer("No encuentro esa encuesta", show_alert=True); return
            keymap = {
                "poll_edit_question": ("cfg_poll_edit_question", "✏️ Envíame la nueva pregunta."),
                "poll_edit_desc": ("cfg_poll_edit_desc", "📝 Envíame la descripción. Escribe QUITAR para dejarla vacía."),
                "poll_edit_options": ("cfg_poll_edit_options", "🔢 Envíame las opciones, una por línea. Máximo 10."),
                "poll_edit_duration": ("cfg_poll_edit_duration", "⏱ Envíame duración: 30m, 2h, 1d o 1sem. Máximo 1 semana."),
                "poll_edit_media": ("cfg_poll_edit_media", "🖼 Envíame foto, vídeo, GIF o documento. Escribe QUITAR para quitar multimedia."),
                "poll_edit_buttons": ("cfg_poll_edit_buttons", "⌨️ Envíame botones:\n<code>Normas=https://...</code>\n<code>Web - https://...</code>\nUsa | para varios. Escribe QUITAR para borrar."),
                "poll_edit_repeat": ("cfg_poll_edit_repeat", "🔁 Envíame repetición: OFF, 30m, 2h, 1d. La encuesta se relanza al terminar."),
            }
            kind, prompt = keymap.get(action, ("", ""))
            if not kind:
                await q.answer(); return
            set_config_pending(q.from_user.id, {"kind": kind, "chat_id": chat_id, "poll_id": pid})
            await q.edit_message_text(prompt, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("❌ Cancelar", callback_data=f"cfg|poll_view|{chat_id}|{pid}|polls")]]))
            return
        if action == "poll_toggle_pin" and len(parts) >= 4:
            pid = int(parts[3]); poll = _v32_poll_find(chat_id, pid)
            if poll:
                poll["pin_notice"] = not bool(poll.get("pin_notice", False)); save_all_states()
                await q.answer("Fijar aviso actualizado")
                await q.edit_message_text(_v33_poll_detail_text(chat_id, poll), parse_mode=ParseMode.HTML, reply_markup=_v33_poll_detail_markup(chat_id, pid))
            return
        if action == "poll_launch" and len(parts) >= 4:
            pid = int(parts[3]); poll = _v32_poll_find(chat_id, pid)
            if poll:
                await _v33_launch_poll(context, chat_id, poll)
                await q.answer("Encuesta lanzada ✅")
                await q.edit_message_text(_v33_poll_detail_text(chat_id, poll), parse_mode=ParseMode.HTML, reply_markup=_v33_poll_detail_markup(chat_id, pid))
            return
        if action == "poll_preview" and len(parts) >= 4:
            pid = int(parts[3]); poll = _v32_poll_find(chat_id, pid)
            if poll:
                await q.answer("Enviando vista previa")
                markup = _v32_poll_markup(chat_id, {**poll, "status": "open"})
                media = poll.get("media") if isinstance(poll.get("media"), dict) else None
                if media and media.get("file_id"):
                    await send_media_blob(context.bot, q.message.chat_id, media, caption=_v32_poll_text({**poll, "status": "open"}, results=False), reply_markup=markup)
                else:
                    await context.bot.send_message(q.message.chat_id, _v32_poll_text({**poll, "status": "open"}, results=False), parse_mode=ParseMode.HTML, reply_markup=markup)
            return
        if action == "poll_delete" and len(parts) >= 4:
            pid = int(parts[3])
            polls = _v32_polls(chat_id)
            poll = _v32_poll_find(chat_id, pid)
            if poll:
                for mid_key in ("message_id", "pin_message_id"):
                    mid = int(poll.get(mid_key, 0) or 0)
                    if mid:
                        try: await context.bot.delete_message(chat_id, mid)
                        except Exception: pass
                polls[:] = [p for p in polls if int(p.get("id",0) or 0) != pid]
                save_all_states()
            await q.answer("Encuesta borrada")
            await q.edit_message_text(admin_private_block_text(chat_id, "polls"), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, "polls"))
            return
    await _old_admin_private_config_callback_v33(update, context)


async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:  # type: ignore[override]
    if not update.effective_user or not update.message or update.effective_chat.type != "private":
        return await _old_admin_private_config_text_v33(update, context)
    pending = get_config_pending(update.effective_user.id)
    if not pending:
        return await _old_admin_private_config_text_v33(update, context)
    kind = str(pending.get("kind") or "")
    if not (kind.startswith("cfg_poll_wizard_") or kind.startswith("cfg_poll_edit_")):
        return await _old_admin_private_config_text_v33(update, context)
    if not is_global_admin_user(update.effective_user.id):
        return True
    chat_id = int(pending.get("chat_id", 0) or 0)
    text = plain_text_from_message(update.message).strip()
    html_text = telegram_html_from_message(update.message).strip()
    if text.upper() in ("CANCELAR", "/CANCELAR"):
        pop_config_pending(update.effective_user.id)
        await update.message.reply_html("❌ Cancelado.", reply_markup=admin_private_block_markup(chat_id, "polls"))
        return True
    if kind == "cfg_poll_wizard_question":
        draft = dict(pending.get("draft") or {}); draft["question"] = text[:250]
        set_config_pending(update.effective_user.id, {"kind": "cfg_poll_wizard_desc", "chat_id": chat_id, "draft": draft})
        await update.message.reply_html("📝 Ahora envíame una <b>descripción</b>. Si no quieres, escribe <code>NO</code>.")
        return True
    if kind == "cfg_poll_wizard_desc":
        draft = dict(pending.get("draft") or {}); draft["description"] = "" if text.upper() in ("NO", "QUITAR", "-") else text[:800]
        set_config_pending(update.effective_user.id, {"kind": "cfg_poll_wizard_options", "chat_id": chat_id, "draft": draft})
        await update.message.reply_html("🔢 Ahora envíame las opciones, una por línea. Ejemplo:\n<code>Bar\nMúsica\nCine</code>")
        return True
    if kind == "cfg_poll_wizard_options":
        opts = [l.strip() for l in text.splitlines() if l.strip()]
        if len(opts) < 2:
            await update.message.reply_text("Necesito mínimo 2 opciones."); return True
        draft = dict(pending.get("draft") or {}); draft["options"] = opts[:10]
        set_config_pending(update.effective_user.id, {"kind": "cfg_poll_wizard_duration", "chat_id": chat_id, "draft": draft})
        await update.message.reply_html("⏱ Duración: <code>30m</code>, <code>2h</code>, <code>1d</code> o <code>1sem</code>. Máximo 1 semana.")
        return True
    if kind == "cfg_poll_wizard_duration":
        draft = dict(pending.get("draft") or {})
        duration = _v33_parse_duration_seconds(text, POLL_DEFAULT_SECONDS_V33)
        poll = {"id": _v32_next_poll_id(chat_id), "question": draft.get("question", "Encuesta"), "description": draft.get("description", ""), "options": draft.get("options", []), "multi": False, "anonymous": True, "status": "draft", "creator_id": int(update.effective_user.id), "created_ts": _v33_now_ts(), "duration_seconds": duration, "close_ts": 0, "message_id": 0, "votes": {}, "media": None, "buttons": [], "pin_notice": False, "repeat_enabled": False, "repeat_seconds": 0, "next_repeat_ts": 0}
        _v32_polls(chat_id).insert(0, poll); save_all_states(); pop_config_pending(update.effective_user.id)
        await update.message.reply_html("✅ Borrador creado. Entra para añadir multimedia, botones, repetición o lanzarla.\n\n" + _v33_poll_detail_text(chat_id, poll), reply_markup=_v33_poll_detail_markup(chat_id, int(poll.get("id"))))
        return True
    pid = int(pending.get("poll_id", 0) or 0)
    poll = _v32_poll_find(chat_id, pid)
    if not poll:
        pop_config_pending(update.effective_user.id); await update.message.reply_html("No encuentro esa encuesta.", reply_markup=admin_private_block_markup(chat_id, "polls")); return True
    if kind == "cfg_poll_edit_question":
        poll["question"] = text[:250] or poll.get("question")
    elif kind == "cfg_poll_edit_desc":
        poll["description"] = "" if text.upper() == "QUITAR" else text[:800]
    elif kind == "cfg_poll_edit_options":
        opts = [l.strip() for l in text.splitlines() if l.strip()]
        if len(opts) < 2:
            await update.message.reply_text("Mínimo 2 opciones."); return True
        poll["options"] = opts[:10]; poll["votes"] = {}
    elif kind == "cfg_poll_edit_duration":
        poll["duration_seconds"] = _v33_parse_duration_seconds(text, POLL_DEFAULT_SECONDS_V33)
        if str(poll.get("status")) == "open":
            poll["close_ts"] = _v33_now_ts() + int(poll["duration_seconds"])
    elif kind == "cfg_poll_edit_buttons":
        poll["buttons"] = [] if text.upper() == "QUITAR" else parse_buttons_text(text)
    elif kind == "cfg_poll_edit_repeat":
        if text.upper() in ("OFF", "NO", "QUITAR"):
            poll["repeat_enabled"] = False; poll["repeat_seconds"] = 0; poll["next_repeat_ts"] = 0
        else:
            poll["repeat_seconds"] = _v33_parse_duration_seconds(text, 3600); poll["repeat_enabled"] = True
    save_all_states(); pop_config_pending(update.effective_user.id)
    if str(poll.get("status")) == "open":
        try: await _v33_send_or_edit_poll_message(context, chat_id, poll)
        except Exception: pass
    await update.message.reply_html("✅ Encuesta actualizada.\n\n" + _v33_poll_detail_text(chat_id, poll), reply_markup=_v33_poll_detail_markup(chat_id, pid))
    return True


async def admin_private_config_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    if not update.effective_user or not update.message or not update.effective_chat or update.effective_chat.type != "private":
        return await _old_admin_private_config_media_v33(update, context)
    pending = get_config_pending(update.effective_user.id)
    if not pending or str(pending.get("kind") or "") != "cfg_poll_edit_media":
        return await _old_admin_private_config_media_v33(update, context)
    if not is_global_admin_user(update.effective_user.id):
        return
    chat_id = int(pending.get("chat_id", 0) or 0); pid = int(pending.get("poll_id", 0) or 0)
    poll = _v32_poll_find(chat_id, pid)
    if not poll:
        pop_config_pending(update.effective_user.id); await update.message.reply_html("No encuentro esa encuesta.", reply_markup=admin_private_block_markup(chat_id, "polls")); return
    media = _v33_extract_media_from_message(update.message)
    if not media:
        txt = plain_text_from_message(update.message).strip().upper()
        if txt == "QUITAR":
            poll["media"] = None; save_all_states(); pop_config_pending(update.effective_user.id)
            await update.message.reply_html("✅ Multimedia quitada.", reply_markup=_v33_poll_detail_markup(chat_id, pid)); return
        await update.message.reply_text("Envía foto, vídeo, GIF o documento, o escribe QUITAR."); return
    poll["media"] = media
    cap = telegram_html_from_message(update.message, caption=True).strip()
    if cap:
        poll["description"] = cap
    save_all_states(); pop_config_pending(update.effective_user.id)
    await update.message.reply_html("✅ Multimedia guardada.\n\n" + _v33_poll_detail_text(chat_id, poll), reply_markup=_v33_poll_detail_markup(chat_id, pid))


async def _v33_private_alert(context: ContextTypes.DEFAULT_TYPE, chat_id: int, text: str, *, message_id: Optional[int] = None) -> None:
    if not bool(cfg_value(chat_id, "owner_private_alerts_enabled", True)):
        return
    targets = set(_v33_owner_ids_env())
    try:
        admins = await context.bot.get_chat_administrators(chat_id)
        for adm in admins:
            if getattr(adm, "status", "") == "creator":
                targets.add(int(adm.user.id))
    except Exception:
        pass
    if not targets:
        return
    link = ""
    if message_id:
        try:
            chat = await context.bot.get_chat(chat_id)
            username = getattr(chat, "username", None)
            link = f"https://t.me/{username}/{message_id}" if username else _message_link_v20(chat_id, message_id)
        except Exception:
            try: link = _message_link_v20(chat_id, message_id)
            except Exception: link = ""
    markup = InlineKeyboardMarkup([[InlineKeyboardButton("➡️ Ir al mensaje", url=link)]]) if link else None
    for uid in targets:
        try:
            await context.bot.send_message(uid, text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
        except Exception:
            pass


