_old_admin_private_config_callback_v45 = admin_private_config_callback
async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    q = update.callback_query
    data = q.data if q else ""
    if q and data.startswith("cfg|ai_"):
        await q.answer()
        parts = data.split("|")
        action = parts[1]
        chat_id = int(parts[2])
        if action == "ai_toggle":
            which = parts[3]
            keymap = {"enabled": "ai_enabled", "auto": "ai_auto_enabled", "good": "ai_good_morning_enabled", "image": "ai_good_morning_image"}
            key = keymap.get(which)
            if key:
                cfg_set(chat_id, key, not bool(cfg_value(chat_id, key, False)))
        elif action == "ai_freq":
            cfg_set(chat_id, "ai_auto_frequency", int(parts[3]))
        elif action == "ai_tone":
            cfg_set(chat_id, "ai_tone", parts[3])
        elif action == "ai_plimit":
            cfg_set(chat_id, "ai_planecito_daily_limit", int(parts[3]))
        elif action == "ai_alimit":
            cfg_set(chat_id, "ai_auto_daily_limit", int(parts[3]))
        elif action == "ai_set_time":
            set_config_pending(q.from_user.id, {"kind": "ai_good_time", "chat_id": chat_id})
            await q.message.reply_html("Escribe la hora para los buenos días IA. Ejemplo: <code>09:30</code>")
            return
        elif action == "ai_test_good":
            await _ai_send_good_morning(context.bot, chat_id, manual=True)
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, "ai"), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, "ai"))
        except Exception:
            await q.message.reply_html(admin_private_block_text(chat_id, "ai"), reply_markup=admin_private_block_markup(chat_id, "ai"))
        return
    await _old_admin_private_config_callback_v45(update, context)


_old_admin_private_config_text_v45 = admin_private_config_text
async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:  # type: ignore[override]
    if update.effective_user and update.message and update.effective_chat.type == "private":
        pending = get_config_pending(update.effective_user.id)
        if pending and pending.get("kind") == "ai_good_time":
            chat_id = int(pending.get("chat_id"))
            value = plain_text_from_message(update.message).strip()
            if not __import__('re').match(r"^\d{1,2}:\d{2}$", value):
                await update.message.reply_html("Formato no válido. Usa algo como <code>09:30</code>.")
                return True
            hh, mm = value.split(":")
            value = f"{int(hh):02d}:{int(mm):02d}"
            cfg_set(chat_id, "ai_good_morning_time", value)
            pop_config_pending(update.effective_user.id)
            await update.message.reply_html("✅ Hora guardada.\n\n" + admin_private_block_text(chat_id, "ai"), reply_markup=admin_private_block_markup(chat_id, "ai"))
            return True
    return await _old_admin_private_config_text_v45(update, context)


_old_build_application_v45 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v45()
    app.add_handler(command_handler("planecito", planecito_command), group=-70)
    app.add_handler(command_handler("tiempo", tiempo_command), group=-70)
    app.add_handler(CallbackQueryHandler(admin_private_config_callback, pattern="^cfg\\|ai_"), group=-86)
    app.add_handler(MessageHandler((filters.TEXT | filters.Caption()) & ~filters.COMMAND, ai_auto_response_handler), group=80)
    try:
        if app.job_queue:
            app.job_queue.run_repeating(ai_daily_tick, interval=60, first=20, name=AI_DAILY_JOB_NAME)
    except Exception:
        logger.exception("No se pudo iniciar job_queue de IA")
    return app



