def _v51_service_markup(chat_id: int) -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    rows.append([InlineKeyboardButton(("✅ " if bool(cfg_value(chat_id, "service_cleanup_enabled", False)) else "❌ ") + "Limpieza automática", callback_data=f"cfg|svc_toggle|{chat_id}|service_cleanup")])
    labels = globals().get("SERVICE_CLEANUP_LABELS", {}) or {}
    if not labels:
        labels = {
            "pinned_message": "📌 Mensaje fijado", "new_chat_photo": "🖼 Foto grupo", "delete_chat_photo": "🗑 Quitar foto",
            "new_chat_title": "✏️ Título", "new_members": "👋 Entradas", "left_member": "🚪 Salidas", "video_chat": "🎧 Videochat", "other": "➕ Otros",
        }
    items = list(labels.items())
    for i in range(0, len(items), 2):
        chunk = items[i:i+2]
        row = []
        for key, label in chunk:
            try:
                active = service_cleanup_type_enabled(chat_id, key)
            except Exception:
                active = False
            row.append(InlineKeyboardButton(("✅ " if active else "❌ ") + str(label), callback_data=f"cfg|svc_type|{chat_id}|{key}|service_cleanup"))
        rows.append(row)
    rows.append([
        InlineKeyboardButton("✅ Activar recomendados", callback_data=f"cfg|svc_preset|{chat_id}|recommended|service_cleanup"),
        InlineKeyboardButton("❌ Todo OFF", callback_data=f"cfg|svc_preset|{chat_id}|off|service_cleanup"),
    ])
    rows.append([InlineKeyboardButton("🔙 Volver", callback_data=f"cfg|home|{chat_id}")])
    return InlineKeyboardMarkup(rows)


