    if block == "service_cleanup": return _v51_service_text(chat_id)
    if block == "command_cleanup": return _v51_command_cleanup_text(chat_id)
    if block == "owner_alerts": return _v51_alerts_text(chat_id)
    if block == "impostor_settings": return _v51_imp_text(chat_id)
    if block == "ai": return _v51_ai_text(chat_id)
    return _old_v51_admin_private_block_text(chat_id, block, page)


