import re as _re_v62

try:
    from telegram.ext import ApplicationHandlerStop
except Exception:  # pragma: no cover
    ApplicationHandlerStop = Exception  # type: ignore

OWNER_IDS = parse_admin_ids(os.getenv("BOT_OWNER_IDS", "")) or set(ADMIN_IDS)

PERMISSION_MODULES_V62 = [
    ("polls", "📊 Encuestas"),
    ("impostor", "🎭 Impostor"),
    ("ai", "🧠 Cerebrito"),
    ("pregonero", "📣 Pregonero"),
    ("daily_phrase", "🌞 Frase del día"),
    ("ai_commands", "⚙️ Comandos IA"),
]
PERMISSION_ROLES_V62 = [
    ("owner", "👑 Dueño"),
    ("admins", "🛡 Admins Telegram"),
    ("admin_ids", "🆔 IDs Admin"),
    ("members", "👥 Miembros"),
]
DEFAULT_PERMISSION_V62 = {
    "polls": "admins",
    "impostor": "members",
    "ai": "members",
    "pregonero": "admins",
    "daily_phrase": "members",
    "ai_commands": "members",
}

try:
    if ("permissions", "🔐 Permisos módulos") not in ADMIN_PRIVATE_BLOCKS:
        ADMIN_PRIVATE_BLOCKS.append(("permissions", "🔐 Permisos módulos"))
    if "ADMIN_PRIVATE_BLOCK_IDS" in globals():
        ADMIN_PRIVATE_BLOCK_IDS.update({"permissions", "ai"})
except Exception:
    pass


def _v62_bool(value: bool) -> str:
    return "ON ✅" if bool(value) else "OFF ❌"


def _v62_role_label(role: str) -> str:
    return dict(PERMISSION_ROLES_V62).get(str(role), str(role))


def _v62_perm_key(module: str) -> str:
    return f"perm_{module}"


def _v62_module_role(chat_id: int, module: str) -> str:
    return str(cfg_value(chat_id, _v62_perm_key(module), DEFAULT_PERMISSION_V62.get(module, "admins")) or DEFAULT_PERMISSION_V62.get(module, "admins"))


async def _v62_is_owner(user_id: int) -> bool:
    return int(user_id) in OWNER_IDS


async def _v62_allowed(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user_id: int, module: str) -> bool:
    role = _v62_module_role(chat_id, module)
    user_id = int(user_id)
    if role == "members":
        return True
    if user_id in OWNER_IDS:
        return True
    if role == "owner":
        return False
    if role == "admin_ids":
        return user_id in ADMIN_IDS
    if role == "admins":
        return await is_admin(context, chat_id, user_id)
    return await is_admin(context, chat_id, user_id)


async def _v62_guard_command(update: Update, context: ContextTypes.DEFAULT_TYPE, module: str) -> bool:
    if not update.effective_chat or not update.effective_user or not update.message:
        return False
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == "private":
        return True
    if not await _v62_allowed(context, chat_id, int(update.effective_user.id), module):
        await update.message.reply_html(f"⛔ Este comando está limitado a: <b>{h(_v62_role_label(_v62_module_role(chat_id, module)))}</b>.")
        raise ApplicationHandlerStop
    return True


async def _v62_guard_ai_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    cmd = ""
    if update.message and update.message.text:
        cmd = update.message.text.split()[0].split('@')[0].lstrip('/').lower()
    chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    module = "ai_commands" if cmd not in ("cerebrito", "planecito", "iatest", "tiempo") else "ai"
    await _v62_guard_command(update, context, module)


async def _v62_guard_impostor_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    await _v62_guard_command(update, context, "impostor")


async def _v62_guard_poll_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    await _v62_guard_command(update, context, "polls")


async def _v62_guard_pregonero_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    await _v62_guard_command(update, context, "pregonero")


async def _v62_guard_daily_phrase_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    await _v62_guard_command(update, context, "daily_phrase")


# -------------------------
# Cerebrito: solo comandos creados + recurrentes IA + borrar comandos.
# -------------------------

def _v62_ai_rows(chat_id: int) -> List[Dict[str, Any]]:
    cfg = admin_cfg(chat_id)
    rows = cfg.setdefault("ai_recurrents", [])
    if not isinstance(rows, list):
        rows = []
        cfg["ai_recurrents"] = rows
    return rows


def _v62_next_id(rows: List[Dict[str, Any]]) -> int:
    try:
        return max([int(r.get("id", 0) or 0) for r in rows] + [0]) + 1
    except Exception:
        return int(time.time())


def _v62_schedule_label(row: Dict[str, Any]) -> str:
    sched = row.get("schedule") if isinstance(row.get("schedule"), dict) else {}
    return str(sched.get("label") or _schedule_label_v20(sched) if '_schedule_label_v20' in globals() else sched.get('type', ''))


def _v62_format_ai_recurrent(row: Dict[str, Any]) -> str:
    state = "ON" if bool(row.get("enabled", True)) else "OFF"
    img = " · imagen" if bool(row.get("image", False)) else ""
    return f"#{row.get('id')} · {h(row.get('name','IA'))} · {h(_v62_schedule_label(row))} · {state}{img}"


async def _v62_send_ai_recurrent(application: Application, chat_id: int, row: Dict[str, Any]) -> Optional[int]:
    prompt = str(row.get("prompt") or "Genera un mensaje corto y divertido para el grupo.").strip()
    name = str(row.get("name") or "Cerebrito")
    answer = await _v57_cerebrito_answer(chat_id, prompt, max_output_tokens=350) if '_v57_cerebrito_answer' in globals() else await _ai_openai_response(chat_id, prompt, max_output_tokens=350)
    text = f"<b>{h(name)}</b>\n\n{h(answer)}"
    try:
        if bool(row.get("image", False)) and '_ai_generate_greeting_image' in globals():
            img = _ai_generate_greeting_image(name, answer[:80])
            if img:
                msg = await application.bot.send_photo(chat_id, photo=img, caption=text[:1000], parse_mode=ParseMode.HTML)
                return int(msg.message_id)
        msg = await application.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML)
        return int(msg.message_id)
    except Exception:
        logger.exception("No se pudo enviar recurrente IA %s en %s", row.get('id'), chat_id)
        return None


async def _v62_ai_recurrent_tick(context: ContextTypes.DEFAULT_TYPE) -> None:
    now = int(time.time())
    now_dt = _local_dt_v15(now) if '_local_dt_v15' in globals() else __import__('datetime').datetime.now()
    for chat_id in list(STATE_CACHE.keys()):
        try:
            for row in _v62_ai_rows(int(chat_id)):
                if not recurring_due(row, now):
                    continue
                # Marca antes para evitar duplicados en carreras.
                row["last_sent_ts"] = now
                sched_type = (row.get("schedule") or {}).get("type") if isinstance(row.get("schedule"), dict) else ""
                if sched_type == "daily":
                    row["last_day"] = now_dt.strftime("%Y-%m-%d")
                elif sched_type == "weekly":
                    row["last_week_key"] = f"{now_dt.strftime('%G-%V')}-{now_dt.weekday()}"
                elif sched_type == "date":
                    row["last_date_key"] = str((row.get("schedule") or {}).get("date", now_dt.strftime("%Y-%m-%d")))
                    row["enabled"] = False
                save_all_states()
                await _v62_send_ai_recurrent(context.application, int(chat_id), row)
                await asyncio.sleep(0.5)
        except Exception:
            logger.exception("Error en recurrente IA chat %s", chat_id)


_old_v62_cerebrito_command = cerebrito_command
async def cerebrito_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    if not update.effective_chat or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if bool(cfg_value(chat_id, "ai_only_custom_commands", False)):
        await update.message.reply_html("🧠 Cerebrito está en modo <b>solo comandos IA creados</b>. Usa uno de los comandos personalizados configurados por admin.")
        return
    return await _old_v62_cerebrito_command(update, context)


async def planecito_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    return await cerebrito_command(update, context)


# -------------------------
# Frase del día con imagen IA/local opcional.
# -------------------------
_old_v62_daily_phrase_maybe_send = daily_phrase_maybe_send
async def daily_phrase_maybe_send(application: Application, chat_id: int, now_ts: int) -> None:  # type: ignore[override]
    if not bool(cfg_value(chat_id, "daily_phrase_ai_image", False)):
        return await _old_v62_daily_phrase_maybe_send(application, chat_id, now_ts)
    cfg = admin_cfg(chat_id)
    if not daily_phrase_due(chat_id, now_ts):
        return
    day_key = _local_dt_v15(now_ts).strftime("%Y-%m-%d") if '_local_dt_v15' in globals() else str(now_ts // 86400)
    if cfg.get("daily_phrase_sending_key") == day_key:
        return
    cfg["daily_phrase_sending_key"] = day_key
    cfg["daily_phrase_last_key"] = day_key
    save_all_states()
    try:
        title = str(cfg.get("daily_phrase_title") or "🌞 Frase del día")
        phrase = daily_phrase_for_date_v15(now_ts)
        caption = f"<b>{h(title)}</b>\n\n<i>{h(phrase)}</i>"
        sent = None
        if '_ai_generate_greeting_image' in globals():
            img = _ai_generate_greeting_image(title, phrase[:90])
            if img:
                sent = await application.bot.send_photo(chat_id, photo=img, caption=caption, parse_mode=ParseMode.HTML)
        if not sent:
            sent = await application.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
        if bool(cfg.get("daily_phrase_pin", False)):
            try:
                await application.bot.pin_chat_message(chat_id, sent.message_id, disable_notification=True)
            except Exception:
                pass
    except Exception:
        cfg["daily_phrase_last_key"] = ""
        logger.exception("No se pudo enviar frase del día con imagen IA")
    finally:
        cfg["daily_phrase_sending_key"] = ""
        save_all_states()


