_old_v62_admin_private_block_text = admin_private_block_text
def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:  # type: ignore[override]
    if block == "permissions":
        lines = ["<b>🔐 Permisos de módulos</b>", f"Grupo: <b>{h(get_chat_title(chat_id))}</b>", ""]
        for key, label in PERMISSION_MODULES_V62:
            lines.append(f"{label}: <b>{h(_v62_role_label(_v62_module_role(chat_id, key)))}</b>")
        lines.append("\nElige quién puede ejecutar cada módulo: dueño, admins de Telegram, IDs admin configurados o todos los miembros.")
        return "\n".join(lines)
    if block == "ai":
        cmds = _ai_custom_commands(chat_id) if '_ai_custom_commands' in globals() else cfg_value(chat_id, "ai_custom_commands", {}) or {}
        recs = _v62_ai_rows(chat_id)
        lines = [
            "<b>🧠 IA Cerebrito</b>",
            f"Grupo: <b>{h(get_chat_title(chat_id))}</b>",
            "",
            f"IA: <b>{_v62_bool(bool(cfg_value(chat_id, 'ai_enabled', True)))}</b>",
            f"Solo comandos creados: <b>{_v62_bool(bool(cfg_value(chat_id, 'ai_only_custom_commands', False)))}</b>",
            f"Auto respuestas: <b>{_v62_bool(bool(cfg_value(chat_id, 'ai_auto_enabled', False)))}</b> · Frecuencia <b>{int(cfg_value(chat_id, 'ai_auto_frequency', 10) or 10)}%</b>",
            f"Tono: <b>{h(cfg_value(chat_id, 'ai_tone', 'divertido'))}</b>",
            f"Prompt extra: <b>{'configurado' if str(cfg_value(chat_id, 'ai_custom_prompt', '') or '').strip() else 'vacío'}</b>",
            f"Comandos IA: <b>{len(cmds) if isinstance(cmds, dict) else 0}</b>",
            f"Recurrentes IA: <b>{len(recs)}</b>",
            f"Imagen en frase del día: <b>{_v62_bool(bool(cfg_value(chat_id, 'daily_phrase_ai_image', False)))}</b>",
            "",
            "Comando principal: <code>/cerebrito pregunta</code>",
            "Crear comando: <code>nombre | instrucciones</code>",
            "Recurrente IA: <code>Nombre | lunes 10:00 | imagen | prompt</code>",
        ]
        return "\n".join(lines)
    try:
        return _old_v62_admin_private_block_text(chat_id, block, page)
    except TypeError:
        return _old_v62_admin_private_block_text(chat_id, block)

_old_v62_admin_private_block_markup = admin_private_block_markup
def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    if block == "permissions":
        rows: List[List[InlineKeyboardButton]] = []
        for key, label in PERMISSION_MODULES_V62:
            role = _v62_module_role(chat_id, key)
            rows.append([InlineKeyboardButton(f"{label}: {_v62_role_label(role)}", callback_data=f"cfg|perm_menu|{chat_id}|{key}")])
        rows.append([InlineKeyboardButton("🔙 Volver", callback_data=f"cfg|home|{chat_id}")])
        return InlineKeyboardMarkup(rows)
    if block == "ai":
        rows = [
            [InlineKeyboardButton(f"🧠 IA {_v62_bool(bool(cfg_value(chat_id, 'ai_enabled', True)))}", callback_data=f"cfg|ai_toggle|{chat_id}|enabled"),
             InlineKeyboardButton(f"🔒 Solo creados {_v62_bool(bool(cfg_value(chat_id, 'ai_only_custom_commands', False)))}", callback_data=f"cfg|ai_only|{chat_id}")],
            [InlineKeyboardButton(f"💬 Auto {_v62_bool(bool(cfg_value(chat_id, 'ai_auto_enabled', False)))}", callback_data=f"cfg|ai_toggle|{chat_id}|auto"),
             InlineKeyboardButton("✏️ Prompt extra", callback_data=f"cfg|ai_custom_prompt|{chat_id}")],
            [InlineKeyboardButton("5%", callback_data=f"cfg|ai_freq|{chat_id}|5"), InlineKeyboardButton("15%", callback_data=f"cfg|ai_freq|{chat_id}|15"), InlineKeyboardButton("30%", callback_data=f"cfg|ai_freq|{chat_id}|30"), InlineKeyboardButton("50%", callback_data=f"cfg|ai_freq|{chat_id}|50")],
            [InlineKeyboardButton("😄 Divertido", callback_data=f"cfg|ai_tone|{chat_id}|divertido"), InlineKeyboardButton("🧠 Serio", callback_data=f"cfg|ai_tone|{chat_id}|serio")],
            [InlineKeyboardButton("😏 Picante", callback_data=f"cfg|ai_tone|{chat_id}|picante"), InlineKeyboardButton("💪 Coach", callback_data=f"cfg|ai_tone|{chat_id}|coach")],
            [InlineKeyboardButton("➕ Crear comando IA", callback_data=f"cfg|ai_cmd_new|{chat_id}"), InlineKeyboardButton("🗑 Borrar comando IA", callback_data=f"cfg|ai_cmd_delete_menu|{chat_id}")],
            [InlineKeyboardButton("📋 Ver comandos IA", callback_data=f"cfg|ai_cmd_list|{chat_id}"), InlineKeyboardButton("🧪 Probar IA", callback_data=f"cfg|ai_test_prompt|{chat_id}")],
            [InlineKeyboardButton("➕ Recurrente IA", callback_data=f"cfg|ai_recur_new|{chat_id}"), InlineKeyboardButton("📅 Recurrentes IA", callback_data=f"cfg|ai_recur_list|{chat_id}")],
            [InlineKeyboardButton(f"🖼 Frase día + imagen {_v62_bool(bool(cfg_value(chat_id, 'daily_phrase_ai_image', False)))}", callback_data=f"cfg|phrase_ai_image|{chat_id}")],
            [InlineKeyboardButton(f"🔐 Permiso IA: {_v62_role_label(_v62_module_role(chat_id, 'ai'))}", callback_data=f"cfg|perm_menu|{chat_id}|ai")],
            [InlineKeyboardButton("🔙 Volver", callback_data=f"cfg|home|{chat_id}")],
        ]
        return InlineKeyboardMarkup(rows)
    try:
        return _old_v62_admin_private_block_markup(chat_id, block, page)
    except TypeError:
        return _old_v62_admin_private_block_markup(chat_id, block)


async def _v62_render_block(q, chat_id: int, block: str) -> None:
    text = admin_private_block_text(chat_id, block)
    markup = admin_private_block_markup(chat_id, block)
    try:
        await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        await q.message.reply_html(text, reply_markup=markup)


async def _v62_render_permissions_for_module(q, chat_id: int, module: str) -> None:
    label = dict(PERMISSION_MODULES_V62).get(module, module)
    role = _v62_module_role(chat_id, module)
    rows = []
    for rkey, rlabel in PERMISSION_ROLES_V62:
        rows.append([InlineKeyboardButton(("✅ " if rkey == role else "") + rlabel, callback_data=f"cfg|perm_set|{chat_id}|{module}|{rkey}")])
    rows.append([InlineKeyboardButton("🔙 Permisos", callback_data=f"cfg|block|{chat_id}|permissions")])
    await q.edit_message_text(f"<b>🔐 Permisos</b>\n\nMódulo: <b>{h(label)}</b>\nActual: <b>{h(_v62_role_label(role))}</b>", parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(rows))


_old_v62_admin_private_config_callback = admin_private_config_callback
async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    q = update.callback_query
    data = q.data if q else ""
    if q and data.startswith("cfg|"):
        parts = data.split("|")
        action = parts[1] if len(parts) > 1 else ""
        try:
            if action == "perm_menu":
                await q.answer()
                await _v62_render_permissions_for_module(q, int(parts[2]), parts[3])
                raise ApplicationHandlerStop
            if action == "perm_set":
                chat_id = int(parts[2]); module = parts[3]; role = parts[4]
                if role not in dict(PERMISSION_ROLES_V62):
                    await q.answer("Rol no válido", show_alert=True); raise ApplicationHandlerStop
                cfg_set(chat_id, _v62_perm_key(module), role)
                await q.answer("Permiso actualizado ✅")
                await _v62_render_permissions_for_module(q, chat_id, module)
                raise ApplicationHandlerStop
            if action == "ai_only":
                chat_id = int(parts[2])
                cfg_set(chat_id, "ai_only_custom_commands", not bool(cfg_value(chat_id, "ai_only_custom_commands", False)))
                await q.answer("Modo actualizado ✅")
                await _v62_render_block(q, chat_id, "ai")
                raise ApplicationHandlerStop
            if action == "phrase_ai_image":
                chat_id = int(parts[2])
                cfg_set(chat_id, "daily_phrase_ai_image", not bool(cfg_value(chat_id, "daily_phrase_ai_image", False)))
                await q.answer("Imagen para frase del día actualizada ✅")
                await _v62_render_block(q, chat_id, "ai")
                raise ApplicationHandlerStop
            if action == "ai_cmd_delete_menu":
                chat_id = int(parts[2])
                cmds = _ai_custom_commands(chat_id) if '_ai_custom_commands' in globals() else {}
                rows = []
                for name in sorted(cmds.keys()):
                    rows.append([InlineKeyboardButton(f"🗑 /{name}", callback_data=f"cfg|ai_cmd_delete|{chat_id}|{name}")])
                rows.append([InlineKeyboardButton("🔙 IA", callback_data=f"cfg|block|{chat_id}|ai")])
                text = "<b>🗑 Borrar comando IA</b>\n\nElige el comando que quieres borrar." if cmds else "<b>🗑 Borrar comando IA</b>\n\nNo tienes comandos IA creados."
                await q.answer()
                await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(rows))
                raise ApplicationHandlerStop
            if action == "ai_cmd_delete":
                chat_id = int(parts[2]); name = parts[3].lower()
                cmds = _ai_custom_commands(chat_id)
                existed = name in cmds
                cmds.pop(name, None)
                save_all_states()
                await q.answer("Comando borrado ✅" if existed else "No existía")
                await _v62_render_block(q, chat_id, "ai")
                raise ApplicationHandlerStop
            if action == "ai_recur_new":
                chat_id = int(parts[2])
                set_config_pending(q.from_user.id, {"kind": "ai_recurrent_new_v62", "chat_id": chat_id})
                await q.answer()
                await q.message.reply_html(
                    "➕ <b>Nuevo recurrente IA</b>\n\nEscribe:\n<code>Nombre | horario | imagen | prompt</code>\n\nEjemplos:\n<code>Buenos días | diario 10:00 | imagen | Genera un buenos días juvenil y divertido para el grupo</code>\n<code>Frase noche | viernes 22:00 | no | Mensaje corto para animar el chat de noche</code>"
                )
                raise ApplicationHandlerStop
            if action == "ai_recur_list":
                chat_id = int(parts[2])
                rows = []
                recs = _v62_ai_rows(chat_id)
                for row in recs[:20]:
                    rid = int(row.get("id", 0) or 0)
                    rows.append([InlineKeyboardButton(_v62_format_ai_recurrent(row)[:60], callback_data=f"cfg|noop|{chat_id}")])
                    rows.append([
                        InlineKeyboardButton("ON/OFF", callback_data=f"cfg|ai_recur_toggle|{chat_id}|{rid}"),
                        InlineKeyboardButton("🗑", callback_data=f"cfg|ai_recur_del|{chat_id}|{rid}"),
                    ])
                rows.append([InlineKeyboardButton("🔙 IA", callback_data=f"cfg|block|{chat_id}|ai")])
                txt = "<b>📅 Recurrentes IA</b>\n\n" + ("\n".join(_v62_format_ai_recurrent(r) for r in recs[:20]) if recs else "No hay recurrentes IA.")
                await q.answer()
                await q.edit_message_text(txt, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(rows))
                raise ApplicationHandlerStop
            if action in ("ai_recur_toggle", "ai_recur_del"):
                chat_id = int(parts[2]); rid = int(parts[3])
                recs = _v62_ai_rows(chat_id)
                for row in list(recs):
                    if int(row.get("id", 0) or 0) == rid:
                        if action == "ai_recur_toggle":
                            row["enabled"] = not bool(row.get("enabled", True))
                        else:
                            recs.remove(row)
                        break
                save_all_states()
                await q.answer("Actualizado ✅")
                await _v62_render_block(q, chat_id, "ai")
                raise ApplicationHandlerStop
        except ApplicationHandlerStop:
            raise
        except Exception:
            logger.exception("Error callback V62")
            try:
                await q.answer("Error. Revisa logs.", show_alert=True)
            except Exception:
                pass
            raise ApplicationHandlerStop
    return await _old_v62_admin_private_config_callback(update, context)


_old_v62_admin_private_config_text = admin_private_config_text
async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:  # type: ignore[override]
    if update.effective_user and update.message and update.effective_chat.type == "private":
        pending = get_config_pending(update.effective_user.id)
        if pending and pending.get("kind") == "ai_recurrent_new_v62":
            chat_id = int(pending.get("chat_id"))
            raw = plain_text_from_message(update.message).strip()
            parts = [p.strip() for p in raw.split("|", 3)]
            if len(parts) < 4:
                await update.message.reply_html("Formato inválido. Usa:<br><code>Nombre | horario | imagen/no | prompt</code>")
                return True
            name, schedule_code, image_flag, prompt = parts
            try:
                sched = recurring_schedule_from_code(schedule_code)
            except Exception:
                await update.message.reply_html("Horario no válido. Ejemplos: <code>diario 10:00</code>, <code>lunes 21:30</code>, <code>cada 2h</code>")
                return True
            rows = _v62_ai_rows(chat_id)
            row = {
                "id": _v62_next_id(rows),
                "name": name[:80] or "Recurrente IA",
                "schedule": sched,
                "prompt": prompt[:2500],
                "image": image_flag.strip().lower() in ("si", "sí", "s", "true", "1", "imagen", "image"),
                "enabled": True,
                "created_ts": int(time.time()),
                "created_by": int(update.effective_user.id),
            }
            rows.append(row)
            pop_config_pending(update.effective_user.id)
            save_all_states()
            await update.message.reply_html("✅ Recurrente IA creado.\n\n" + admin_private_block_text(chat_id, "ai"), reply_markup=admin_private_block_markup(chat_id, "ai"))
            return True
    return await _old_v62_admin_private_config_text(update, context)


# -------------------------
# Guardas de permisos para comandos principales.
# -------------------------
_old_v62_build_application = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_v62_build_application()
    # Guards de permisos en grupos. Si permiten, no detienen el flujo.
    app.add_handler(command_handler("cerebrito", _v62_guard_ai_command), group=-200000)
    app.add_handler(command_handler("planecito", _v62_guard_ai_command), group=-200000)
    app.add_handler(command_handler("iatest", _v62_guard_ai_command), group=-200000)
    app.add_handler(command_handler("tiempo", _v62_guard_ai_command), group=-200000)
    app.add_handler(command_handler("impostor", _v62_guard_impostor_command), group=-200000)
    app.add_handler(command_handler("impostorstop", _v62_guard_impostor_command), group=-200000)
    app.add_handler(command_handler("impostorskip", _v62_guard_impostor_command), group=-200000)
    app.add_handler(command_handler("impostorexpulsar", _v62_guard_impostor_command), group=-200000)
    app.add_handler(command_handler("encuesta", _v62_guard_poll_command), group=-200000)
    app.add_handler(command_handler("encuestas", _v62_guard_poll_command), group=-200000)
    app.add_handler(command_handler("pregonero", _v62_guard_pregonero_command), group=-200000)
    app.add_handler(command_handler("pregoneroauto", _v62_guard_pregonero_command), group=-200000)
    app.add_handler(command_handler("frasedia", _v62_guard_daily_phrase_command), group=-200000)
    # Router de config V62 muy prioritario.
    app.add_handler(CallbackQueryHandler(admin_private_config_callback, pattern=r"^cfg\|(perm_|ai_only|phrase_ai_image|ai_cmd_delete|ai_recur)"), group=-200000)
    app.add_handler(MessageHandler((filters.TEXT | filters.Caption()) & ~filters.COMMAND, admin_private_config_text), group=-200000)
    # Custom AI commands guard: antes del handler real de custom commands.
    app.add_handler(MessageHandler(filters.COMMAND, _v62_guard_ai_command), group=-200001)
    try:
        if app.job_queue:
            app.job_queue.run_repeating(_v62_ai_recurrent_tick, interval=60, first=30, name="ai_recurrent_v62_tick")
    except Exception:
        logger.exception("No se pudo iniciar job de recurrentes IA")
    logger.info("V62 IA avanzada, permisos y recurrentes cargado")
    return app


# ============================================================
# V63 - Reparación definitiva de menús IA / Permisos / Borrado comandos
# - IA Cerebrito y Permisos aparecen en /ajustes y abren correctamente.
# - Borrado comandos incluye opción 2 segundos visible y funcional.
# - Router prioritario evita que callbacks antiguos bloqueen esos paneles.
# ============================================================

try:
    from telegram.ext import ApplicationHandlerStop as _V63Stop
except Exception:  # pragma: no cover
    _V63Stop = Exception  # type: ignore


def _v63_ensure_private_blocks() -> None:
    """Deja el menú de /ajustes en un orden estable.

    El sistema antiguo asumía que el último bloque era 'lists'. En V62 se añadió
    'permissions' al final, lo que hacía que a veces no se mostrara o no abriera.
    Aquí recolocamos IA y Permisos antes de Listados y dejamos Listados siempre
    como último bloque ancho.
    """
    global ADMIN_PRIVATE_BLOCKS, ADMIN_PRIVATE_BLOCK_IDS
    wanted_extra = [("ai", "🧠 IA Cerebrito"), ("permissions", "🔐 Permisos módulos")]
    # Elimina duplicados de ai / permissions / lists conservando el resto.
    cleaned = []
    seen = set()
    for key, label in list(ADMIN_PRIVATE_BLOCKS):
        if key in {"ai", "permissions", "lists"}:
            continue
        if key in seen:
            continue
        seen.add(key)
        cleaned.append((key, label))
    # Inserta antes del bloque ancho final.
    cleaned.extend(wanted_extra)
    cleaned.append(("lists", "📊 Listados y control"))
    ADMIN_PRIVATE_BLOCKS = cleaned
    ADMIN_PRIVATE_BLOCK_IDS = {key for key, _label in ADMIN_PRIVATE_BLOCKS}


_v63_ensure_private_blocks()


async def _v63_render_query(q, text: str, markup=None) -> None:
    try:
        await q.answer()
    except Exception:
        pass
    try:
        await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
        return
    except Exception:
        pass
    try:
        await q.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        pass


_old_v63_admin_private_main_markup = admin_private_main_markup
def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:  # type: ignore[override]
    _v63_ensure_private_blocks()
    rows: List[List[InlineKeyboardButton]] = []
    normal_blocks = [(k, l) for k, l in ADMIN_PRIVATE_BLOCKS if k != "lists"]
    for i in range(0, len(normal_blocks), 2):
        chunk = normal_blocks[i:i+2]
        rows.append([
            InlineKeyboardButton(block_label(chat_id, key, label), callback_data=f"cfg|block|{chat_id}|{key}")
            for key, label in chunk
        ])
    try:
        state = get_state(chat_id)
        pending_count = sum(1 for r in state.validation_users.values() if r.get("status") in ("answering", "pending_admin", "timeout"))
        log_count = len([r for r in state.action_log if int(r.get("ts") or 0) >= _now_ts() - 3 * 86400])
        lists_label = (
            f"{admin_block_icon(chat_id, 'lists')} 📊 LISTADOS Y CONTROL "
            f"· 👥 {pending_count} · 📜 {log_count} · 🚫 {len(state.expelled_users)}"
        )
    except Exception:
        lists_label = "📊 LISTADOS Y CONTROL"
    rows.append([InlineKeyboardButton(lists_label, callback_data=f"cfg|block|{chat_id}|lists")])
    rows.append([
        InlineKeyboardButton("🔄 Reload", callback_data=f"cfg|reload|{chat_id}"),
        InlineKeyboardButton("💾 Guardar", callback_data=f"cfg|save|{chat_id}"),
        InlineKeyboardButton("❌ Cerrar panel", callback_data=f"cfg|close|{chat_id}"),
    ])
    rows.append([InlineKeyboardButton("🔙 Elegir otro grupo", callback_data="cfg|list")])
    return InlineKeyboardMarkup(rows)


_old_v63_admin_private_block_text = admin_private_block_text
def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:  # type: ignore[override]
    _v63_ensure_private_blocks()
    if block == "command_cleanup":
        title = str(cfg_value(chat_id, "chat_title", "") or get_chat_title(chat_id) or chat_id)
        return (
            "<b>🧹 Bloque Borrado de comandos</b>\n"
            f"Grupo: <b>{h(title)}</b>\n\n"
            f"Estado actual: <b>{h(command_cleanup_label(chat_id))}</b>\n\n"
            "Este ajuste borra solo el mensaje donde un usuario escribe un comando del bot. "
            "No borra mensajes normales, paneles, pistas ni mensajes recurrentes.\n\n"
            "Opciones disponibles:\n"
            "• <b>No borrar</b>\n"
            "• <b>Al ejecutar</b>\n"
            "• <b>A los 2 segundos</b>\n"
            "• <b>A los 5 segundos</b>\n"
            "• <b>A los 30 segundos</b>"
        )
    try:
        return _old_v63_admin_private_block_text(chat_id, block, page)
    except TypeError:
        return _old_v63_admin_private_block_text(chat_id, block)


_old_v63_admin_private_block_markup = admin_private_block_markup
def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    _v63_ensure_private_blocks()
    if block == "command_cleanup":
        def st(preset: str) -> str:
            try:
                return command_cleanup_status(chat_id, preset)
            except Exception:
                mode = str(cfg_value(chat_id, "command_cleanup_mode", "off"))
                ttl = int(cfg_value(chat_id, "command_cleanup_ttl_seconds", 0) or 0)
                if preset == "off":
                    return "✅" if mode == "off" else "❌"
                if preset == "instant":
                    return "✅" if mode == "instant" else "❌"
                return "✅" if mode == "ttl" and ttl == int(preset) else "❌"
        rows = [
            [
                InlineKeyboardButton(f"{st('off')} No borrar", callback_data=f"cfg|cleanup_set|{chat_id}|off|command_cleanup"),
                InlineKeyboardButton(f"{st('instant')} Al ejecutar", callback_data=f"cfg|cleanup_set|{chat_id}|instant|command_cleanup"),
            ],
            [
                InlineKeyboardButton(f"{st('2')} A los 2s", callback_data=f"cfg|cleanup_set|{chat_id}|2|command_cleanup"),
                InlineKeyboardButton(f"{st('5')} A los 5s", callback_data=f"cfg|cleanup_set|{chat_id}|5|command_cleanup"),
                InlineKeyboardButton(f"{st('30')} A los 30s", callback_data=f"cfg|cleanup_set|{chat_id}|30|command_cleanup"),
            ],
        ]
        rows.extend(block_footer_rows(chat_id, block))
        return InlineKeyboardMarkup(rows)
    return _old_v63_admin_private_block_markup(chat_id, block, page)


async def _v63_cfg_priority_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ""
    if not data.startswith("cfg|"):
        return
    parts = data.split("|")
    action = parts[1] if len(parts) > 1 else ""

    # Selector de grupos / cerrar / guardar / volver: manejo directo y seguro.
    try:
        if data == "cfg|list":
            await _v63_render_query(q, "<b>Elige el grupo que quieres configurar:</b>", admin_private_chat_list_markup())
            raise _V63Stop
        if action == "close":
            try:
                await q.answer("Guardado ✅")
            except Exception:
                pass
            try:
                await q.message.delete()
            except Exception:
                await _v63_render_query(q, "✅ Panel guardado y cerrado.", None)
            raise _V63Stop
        if action in {"open", "home", "reload", "save"} and len(parts) >= 3:
            chat_id = int(parts[2])
            if action == "save":
                save_all_states()
            await _v63_render_query(q, admin_private_main_text(chat_id), admin_private_main_markup(chat_id))
            raise _V63Stop
        if action in {"block", "block_reload", "block_save"} and len(parts) >= 4:
            chat_id = int(parts[2])
            block = parts[3]
            if block not in ADMIN_PRIVATE_BLOCK_IDS:
                block = "validation"
            if action == "block_save":
                save_all_states()
            await _v63_render_query(q, admin_private_block_text(chat_id, block), admin_private_block_markup(chat_id, block))
            raise _V63Stop
        if action == "cleanup_set" and len(parts) >= 4:
            chat_id = int(parts[2])
            preset = str(parts[3])
            if preset == "off":
                cfg_set(chat_id, "command_cleanup_mode", "off")
                cfg_set(chat_id, "command_cleanup_ttl_seconds", 0)
            elif preset == "instant":
                cfg_set(chat_id, "command_cleanup_mode", "instant")
                cfg_set(chat_id, "command_cleanup_ttl_seconds", 0)
            else:
                cfg_set(chat_id, "command_cleanup_mode", "ttl")
                cfg_set(chat_id, "command_cleanup_ttl_seconds", max(1, int(preset)))
            await _v63_render_query(q, admin_private_block_text(chat_id, "command_cleanup"), admin_private_block_markup(chat_id, "command_cleanup"))
            raise _V63Stop
    except _V63Stop:
        raise
    except Exception:
        logger.exception("Error en router prioritario V63: %s", data)
        try:
            await q.answer("Error abriendo el menú. Revisa logs.", show_alert=True)
        except Exception:
            pass
        raise _V63Stop
    # Si no es una acción de navegación/cleanup, dejamos que los routers específicos
    # de IA, permisos, recurrentes, impostor, etc. hagan su trabajo.
    return


_old_v63_build_application = build_application
def build_application() -> Application:  # type: ignore[override]
    _v63_ensure_private_blocks()
    app = _old_v63_build_application()
    # Máxima prioridad para navegación de /ajustes y limpieza de comandos.
    app.add_handler(CallbackQueryHandler(_v63_cfg_priority_router, pattern=r"^cfg\|"), group=-1000000)
    logger.info("V63 menús IA/Permisos/Borrado comandos corregidos")
    return app



# =========================
# V65 - Botones de recurrentes que ejecutan comandos seguros del bot
# =========================
# Uso en botones de mensajes recurrentes:
#   🎯 Preguntita=cmd:preguntita | 🎲 Retito=cmd:retito | 📜 Normas=cmd:normas
# También acepta command:preguntita o /preguntita.

_V65_ALLOWED_REC_COMMANDS = {
    "preguntita", "retito", "retohot", "rankinghot", "normas", "reglas",
    "impostor", "impostorstop", "djmesa", "frasedia", "resumencito", "resumen",
    "ping", "cerebrito",
}


def _v65_clean_rec_cmd(value: str) -> str:
    raw = str(value or "").strip()
    low = raw.lower()
    for pref in ("cmd:", "command:"):
        if low.startswith(pref):
            raw = raw[len(pref):].strip()
            break
    raw = raw.lstrip("/").strip()
    # Permitimos solo el nombre del comando; sin argumentos para evitar abusos.
    raw = raw.split()[0] if raw.split() else ""
    clean = "".join(ch for ch in raw.lower() if ch.isalnum() or ch in ("_",))[:32]
    if clean == "normas":
        clean = "reglas"
    if clean == "retohot":
        clean = "retito"
    return clean


def _v65_is_cmd_url(value: str) -> bool:
    low = str(value or "").strip().lower()
    return low.startswith("cmd:") or low.startswith("command:") or low.startswith("/")


# Guardamos referencia por si alguna ruta antigua la necesitara.
_old_v65_recurring_parse_buttons_private = recurring_parse_buttons_private

def recurring_parse_buttons_private(text: str) -> List[Dict[str, str]]:  # type: ignore[override]
    """Parsea botones de recurrentes.

    Formatos soportados:
      Texto=https://...
      Ver mensaje=auto
      Preguntita=cmd:preguntita
      Normas=/reglas
    """
    buttons: List[Dict[str, str]] = []
    for chunk in (text or "").replace("\n", "|").split("|"):
        part = chunk.strip()
        if not part:
            continue
        if "=" in part:
            label, target = part.split("=", 1)
        elif " - " in part:
            label, target = part.split(" - ", 1)
        else:
            continue
        label = label.strip()[:64]
        target = target.strip()
        if not label or not target:
            continue
        if target.startswith("t.me/"):
            target = "https://" + target
        if _v65_is_cmd_url(target):
            cmd = _v65_clean_rec_cmd(target)
            if cmd in _V65_ALLOWED_REC_COMMANDS:
                buttons.append({"text": label, "cmd": cmd})
            continue
        if target.startswith("http://") or target.startswith("https://") or target.startswith("tg://"):
            buttons.append({"text": label, "url": target})
            continue
        if _is_self_url_v20(target):
            buttons.append({"text": label, "url": "self"})
    return buttons[:20]


def recurring_buttons_markup(row: Dict[str, Any], self_url: Optional[str] = None, chat_id: Optional[int] = None) -> Optional[InlineKeyboardMarkup]:  # type: ignore[override]
    buttons = row.get("buttons") or []
    if not isinstance(buttons, list) or not buttons:
        return None
    rows: List[List[InlineKeyboardButton]] = []
    for b in buttons:
        if not isinstance(b, dict):
            continue
        text = str(b.get("text", "")).strip()[:64]
        if not text:
            continue
        cmd = _v65_clean_rec_cmd(str(b.get("cmd", ""))) if b.get("cmd") else ""
        if cmd:
            if chat_id is not None and cmd in _V65_ALLOWED_REC_COMMANDS:
                rows.append([InlineKeyboardButton(text, callback_data=f"reccmd|{int(chat_id)}|{cmd}")])
            continue
        url = str(b.get("url", "")).strip()
        if _is_self_url_v20(url) or url == "self":
            if self_url:
                rows.append([InlineKeyboardButton(text, url=self_url)])
        elif url.startswith("http://") or url.startswith("https://") or url.startswith("tg://"):
            rows.append([InlineKeyboardButton(text, url=url)])
    return InlineKeyboardMarkup(rows) if rows else None


async def send_recurring_message(context, chat_id: int, row: Dict[str, Any]) -> Optional[int]:  # type: ignore[override]
    """Versión V65: permite self-url y botones cmd: en recurrentes."""
    text = str(row.get("text") or "").strip()
    media = row.get("media") if isinstance(row.get("media"), dict) else None
    msg = None
    previous_message_id = int(row.get("last_message_id") or 0)
    delete_previous = bool(row.get("delete_previous", True))

    try:
        markup_initial = recurring_buttons_markup(row, self_url=None, chat_id=int(chat_id))
        if media and media.get("file_id"):
            fid = media.get("file_id")
            mtype = media.get("type")
            if mtype == "photo":
                msg = await context.bot.send_photo(chat_id, photo=fid, caption=text or None, parse_mode=ParseMode.HTML, reply_markup=markup_initial)
            elif mtype == "video":
                msg = await context.bot.send_video(chat_id, video=fid, caption=text or None, parse_mode=ParseMode.HTML, reply_markup=markup_initial)
            elif mtype == "animation":
                msg = await context.bot.send_animation(chat_id, animation=fid, caption=text or None, parse_mode=ParseMode.HTML, reply_markup=markup_initial)
            else:
                msg = await context.bot.send_document(chat_id, document=fid, caption=text or None, parse_mode=ParseMode.HTML, reply_markup=markup_initial)
        else:
            msg = await context.bot.send_message(chat_id, text=text or "Mensaje recurrente", parse_mode=ParseMode.HTML, reply_markup=markup_initial, disable_web_page_preview=True)

        await register_bot_message(chat_id, msg.message_id)
        self_url = _message_link_v20(chat_id, msg.message_id)
        markup_final = recurring_buttons_markup(row, self_url=self_url, chat_id=int(chat_id))
        if markup_final:
            try:
                await context.bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=markup_final)
            except Exception:
                pass

        if bool(row.get("pin", False)):
            try:
                await context.bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
            except Exception:
                logger.exception("No se pudo fijar recurrente %s en chat %s", row.get("id"), chat_id)

        row["last_message_id"] = int(msg.message_id)
        row["last_message_link"] = self_url
        row["delete_previous"] = delete_previous
        try:
            row["schedule_label"] = _schedule_label_v20(row.get("schedule") or {}) or str(row.get("schedule_label") or "")
        except Exception:
            pass
        save_all_states()

        if delete_previous and previous_message_id and previous_message_id != int(msg.message_id):
            try:
                await safe_delete(context.bot, chat_id, previous_message_id)
            except Exception:
                pass
        return int(msg.message_id)
    except Exception:
        logger.exception("No se pudo enviar recurrente %s en chat %s", row.get("id"), chat_id)
        return None


async def _v65_send_hot_item_from_button(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, kind: str) -> None:
    hot_activity_remember(chat_id, user)
    level = hot_pick_level(chat_id, automatic=False)
    if kind == "challenge":
        body = hot_get_challenge(chat_id, level)
        title = f"😈 <b>Retito · Nivel {level}</b>"
        line = f"🎲 {h(body)}"
        reg_kind = "challenge"
    else:
        body = hot_get_question(chat_id, level)
        title = f"🔥 <b>Preguntita · Nivel {level}</b>"
        line = f"💬 {h(body)}"
        reg_kind = "question"
    text = f"🎯 {user.mention_html()}\n\n{title}\n\n{line}"
    msg = await context.bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML)
    await register_bot_message(chat_id, msg.message_id)
    hot_register_question(chat_id, msg.message_id, user, level, kind=reg_kind)
    asyncio.create_task(hot_safe_delete(context, chat_id, msg.message_id))


async def _v65_send_rankinghot_from_button(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    ranking = hot_cfg(chat_id).get("hot_ranking", {}) or {}
    rows = []
    for row in ranking.values():
        try:
            rows.append((str(row.get("name") or "Usuario"), int(row.get("points", 0) or 0)))
        except Exception:
            pass
    rows.sort(key=lambda x: x[1], reverse=True)
    if not rows:
        text = "🏆 <b>Ranking HOT</b>\n\nTodavía no hay puntos."
    else:
        text = "🏆 <b>Ranking HOT</b>\n\n" + "\n".join(f"{i}. {h(n)} — <b>{p}</b> pts" for i, (n, p) in enumerate(rows[:10], 1))
    await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML)


async def _v65_start_impostor_from_button(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user) -> None:
    active = next((g for g in _imp_games(chat_id) if str(g.get("status")) in ("lobby", "active", "voting")), None)
    if active:
        # Si hay lobby, intentamos unir al usuario directamente.
        if str(active.get("status")) == "lobby":
            players = active.setdefault("players", [])
            if not any(int(p.get("id", 0) or 0) == int(user.id) for p in players):
                players.append({"id": int(user.id), "name": display_name(user)})
                save_all_states()
                try:
                    await context.bot.edit_message_text(chat_id=chat_id, message_id=int(active.get("message_id") or 0), text=_imp_lobby_text(active), parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, active))
                except Exception:
                    pass
                await context.bot.send_message(chat_id, f"🎭 {user.mention_html()} se ha unido a la partida.", parse_mode=ParseMode.HTML)
            else:
                await context.bot.send_message(chat_id, "🎭 Ya estás dentro de la partida.")
        else:
            await context.bot.send_message(chat_id, "🎭 Ya hay una partida de Impostor en marcha.")
        return
    word = secrets.choice(IMPOSTOR_WORDS)
    gid = _imp_next_id(chat_id)
    game = {
        "id": gid,
        "status": "lobby",
        "word": word,
        "creator_id": int(user.id),
        "created_ts": int(time.time()),
        "players": [{"id": int(user.id), "name": display_name(user)}],
        "round": 1,
        "turn_idx": 0,
        "votes": {},
        "impostor_id": 0,
        "message_id": 0,
    }
    msg = await context.bot.send_message(chat_id, _imp_lobby_text(game), parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, game))
    game["message_id"] = msg.message_id
    _imp_games(chat_id).insert(0, game)
    save_all_states()


async def _v65_recurring_command_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    try:
        await q.answer("Ejecutando…")
    except Exception:
        pass
    parts = (q.data or "").split("|", 2)
    if len(parts) < 3:
        return
    try:
        chat_id = int(parts[1])
    except Exception:
        chat_id = int(q.message.chat_id) if q.message else 0
    cmd = _v65_clean_rec_cmd(parts[2])
    user = q.from_user

    try:
        if not chat_id or not chat_is_allowed(chat_id):
            return
        if cmd == "preguntita":
            await _v65_send_hot_item_from_button(context, chat_id, user, "question")
        elif cmd == "retito":
            await _v65_send_hot_item_from_button(context, chat_id, user, "challenge")
        elif cmd == "rankinghot":
            await _v65_send_rankinghot_from_button(context, chat_id)
        elif cmd == "reglas":
            await context.bot.send_message(chat_id, str(cfg_value(chat_id, "rules_text")), parse_mode=ParseMode.HTML)
        elif cmd == "impostor":
            await _v65_start_impostor_from_button(context, chat_id, user)
        elif cmd == "impostorstop":
            if await is_admin(context, chat_id, user.id):
                for g in _imp_games(chat_id):
                    if str(g.get("status")) in ("lobby", "active", "voting"):
                        g["status"] = "cancelled"; save_all_states()
                        await context.bot.send_message(chat_id, "🎭 Partida de Impostor cancelada.")
                        return
                await context.bot.send_message(chat_id, "No hay partida activa.")
            else:
                await context.bot.send_message(chat_id, "Solo administradores pueden cancelar una partida.")
        elif cmd == "djmesa":
            state = get_state(chat_id)
            if not state.dj_mode:
                await context.bot.send_message(chat_id, "🎛 El modo DJ no está activo.")
            else:
                try:
                    await render_control_home(context.bot, chat_id)
                except Exception:
                    await ensure_control_panel(context.bot, chat_id)
        elif cmd == "frasedia":
            try:
                phrase = daily_phrase_for_chat_v30(chat_id)
            except Exception:
                phrase = daily_phrase_for_date_v15()
            await context.bot.send_message(chat_id, f"🌞 <b>Frase del día</b>\n\n{h(phrase)}", parse_mode=ParseMode.HTML)
        elif cmd in ("resumen", "resumencito"):
            await context.bot.send_message(chat_id, "📖 Para generar el resumen divertido, escribe <code>/resumencito</code> en el grupo.", parse_mode=ParseMode.HTML)
        elif cmd == "ping":
            await context.bot.send_message(chat_id, "🏓 Pong. Bot activo ✅")
        elif cmd == "cerebrito":
            await context.bot.send_message(chat_id, "🧠 Usa <code>/cerebrito tu pregunta</code> para consultar a Cerebrito.", parse_mode=ParseMode.HTML)
        else:
            await context.bot.send_message(chat_id, "Ese comando de botón no está permitido.")
    except Exception:
        logger.exception("Error ejecutando botón de recurrente: %s", q.data)
        try:
            await q.answer("Error ejecutando el comando. Revisa logs.", show_alert=True)
        except Exception:
            pass


_old_v65_build_application = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_v65_build_application()
    # Muy prioritario para que los botones cmd: de recurrentes no caigan en otros routers.
    app.add_handler(CallbackQueryHandler(_v65_recurring_command_callback, pattern=r"^reccmd\|"), group=-1100000)
    logger.info("V65 botones de recurrentes con cmd: activados")
    return app



# =========================
# V66 - Recurrentes: comandos permitidos configurables para botones
# =========================
# Ahora los botones de recurrentes pueden ejecutar comandos si y solo si el
# comando está en la lista configurable del grupo:
#   /ajustes -> Mensajes recurrentes -> ⚙️ Comandos permitidos
# Formato en botones:
#   Preguntita=cmd:preguntita | Normas=/reglas | Impostor=cmd:impostor

from telegram.ext import ApplicationHandlerStop

_V66_DEFAULT_REC_COMMANDS = [
    "preguntita", "retito", "retohot", "rankinghot", "reglas", "normas",
    "impostor", "impostorstop", "djmesa", "frasedia", "resumencito", "resumen",
    "ping", "cerebrito",
]


def _v66_clean_cmd_name(value: str) -> str:
    raw = str(value or "").strip()
    low = raw.lower()
    for pref in ("cmd:", "command:"):
        if low.startswith(pref):
            raw = raw[len(pref):].strip()
            break
    raw = raw.lstrip("/").strip()
    raw = raw.split()[0] if raw.split() else ""
    clean = "".join(ch for ch in raw.lower() if ch.isalnum() or ch == "_")[:32]
    return clean


def _v66_allowed_rec_commands(chat_id: int) -> List[str]:
    raw = cfg_value(chat_id, "recurring_button_allowed_commands", None)
    if raw is None:
        # Primera vez: dejamos una lista útil por defecto para no romper botones ya creados.
        cfg_set(chat_id, "recurring_button_allowed_commands", list(_V66_DEFAULT_REC_COMMANDS))
        raw = list(_V66_DEFAULT_REC_COMMANDS)
    if isinstance(raw, str):
        raw = [p.strip() for p in raw.replace(";", ",").split(",") if p.strip()]
    if not isinstance(raw, list):
        raw = []
    result: List[str] = []
    for item in raw:
        cmd = _v66_clean_cmd_name(str(item))
        if cmd and cmd not in result:
            result.append(cmd)
    return result


def _v66_set_allowed_rec_commands(chat_id: int, commands: List[str]) -> None:
    clean: List[str] = []
    for c in commands:
        cmd = _v66_clean_cmd_name(c)
        if cmd and cmd not in clean:
            clean.append(cmd)
    cfg_set(chat_id, "recurring_button_allowed_commands", clean)


def _v66_rec_cmds_text(chat_id: int) -> str:
    allowed = _v66_allowed_rec_commands(chat_id)
    lines = [
        "<b>⚙️ Comandos permitidos en botones recurrentes</b>",
        f"Grupo: <b>{h(get_chat_title(chat_id) if 'get_chat_title' in globals() else str(chat_id))}</b>",
        "",
        "Solo se ejecutarán comandos que estén en esta lista.",
        "Si un botón tiene <code>cmd:comando</code> y el comando no está permitido, el bot lo bloqueará.",
        "",
        "<b>Permitidos ahora:</b>",
    ]
    if allowed:
        lines.extend(f"• <code>/{h(cmd)}</code>" for cmd in allowed)
    else:
        lines.append("<i>Ninguno. Los botones de comando no se ejecutarán.</i>")
    lines.extend([
        "",
        "<b>Cómo usarlo en un recurrente:</b>",
        "<code>🎯 Preguntita=cmd:preguntita | 📜 Normas=/reglas</code>",
        "",
        "Puedes añadir cualquier comando del bot. Los permisos normales del comando seguirán aplicándose.",
    ])
    return "\n".join(lines)


def _v66_rec_cmds_markup(chat_id: int) -> InlineKeyboardMarkup:
    allowed = _v66_allowed_rec_commands(chat_id)
    rows: List[List[InlineKeyboardButton]] = []
    rows.append([
        InlineKeyboardButton("➕ Añadir comando", callback_data=f"cfg|rec_cmd_add|{chat_id}|recurrentes"),
        InlineKeyboardButton("🧹 Vaciar lista", callback_data=f"cfg|rec_cmd_clear|{chat_id}|recurrentes"),
    ])
    rows.append([
        InlineKeyboardButton("✅ Restaurar básicos", callback_data=f"cfg|rec_cmd_defaults|{chat_id}|recurrentes"),
    ])
    for cmd in allowed[:30]:
        rows.append([
            InlineKeyboardButton(f"/{cmd}", callback_data=f"cfg|noop|{chat_id}|recurrentes"),
            InlineKeyboardButton("🗑 Quitar", callback_data=f"cfg|rec_cmd_remove|{chat_id}|{cmd}|recurrentes"),
        ])
    rows.append([InlineKeyboardButton("🔙 Volver a recurrentes", callback_data=f"cfg|block|{chat_id}|recurrentes")])
    rows.append([InlineKeyboardButton("💾 Guardar y cerrar", callback_data=f"cfg|close|{chat_id}")])
    return InlineKeyboardMarkup(rows)


# Sobrescribimos parser para aceptar cualquier cmd: y guardarlo; se valida al renderizar/ejecutar.
def recurring_parse_buttons_private(text: str) -> List[Dict[str, str]]:  # type: ignore[override]
    buttons: List[Dict[str, str]] = []
    for chunk in (text or "").replace("\n", "|").split("|"):
        part = chunk.strip()
        if not part:
            continue
        if "=" in part:
            label, target = part.split("=", 1)
        elif " - " in part:
            label, target = part.split(" - ", 1)
        else:
            continue
        label = label.strip()[:64]
        target = target.strip()
        if not label or not target:
            continue
        if target.startswith("t.me/"):
            target = "https://" + target
        if _v65_is_cmd_url(target):
            cmd = _v66_clean_cmd_name(target)
            if cmd:
                buttons.append({"text": label, "cmd": cmd})
            continue
        if target.startswith("http://") or target.startswith("https://") or target.startswith("tg://"):
            buttons.append({"text": label, "url": target})
            continue
        if _is_self_url_v20(target):
            buttons.append({"text": label, "url": "self"})
    return buttons[:20]


# Botones recurrentes: solo se pintan/activan si el comando está permitido en ese grupo.
def recurring_buttons_markup(row: Dict[str, Any], self_url: Optional[str] = None, chat_id: Optional[int] = None) -> Optional[InlineKeyboardMarkup]:  # type: ignore[override]
    buttons = row.get("buttons") or []
    if not isinstance(buttons, list) or not buttons:
        return None
    allowed = set(_v66_allowed_rec_commands(int(chat_id))) if chat_id is not None else set()
    rows: List[List[InlineKeyboardButton]] = []
    for b in buttons:
        if not isinstance(b, dict):
            continue
        text = str(b.get("text", "")).strip()[:64]
        if not text:
            continue
        cmd = _v66_clean_cmd_name(str(b.get("cmd", ""))) if b.get("cmd") else ""
        if cmd:
            if chat_id is not None and cmd in allowed:
                rows.append([InlineKeyboardButton(text, callback_data=f"reccmd|{int(chat_id)}|{cmd}")])
            continue
        url = str(b.get("url", "")).strip()
        if _is_self_url_v20(url) or url == "self":
            if self_url:
                rows.append([InlineKeyboardButton(text, url=self_url)])
        elif url.startswith("http://") or url.startswith("https://") or url.startswith("tg://"):
            rows.append([InlineKeyboardButton(text, url=url)])
    return InlineKeyboardMarkup(rows) if rows else None


_old_v66_admin_private_block_text = admin_private_block_text
def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:  # type: ignore[override]
    text = _old_v66_admin_private_block_text(chat_id, block, page)
    if block == "recurrentes":
        allowed = _v66_allowed_rec_commands(chat_id)
        label = ", ".join(f"/{c}" for c in allowed[:8]) if allowed else "ninguno"
        if len(allowed) > 8:
            label += f" … +{len(allowed)-8}"
        text += "\n\n<b>Botones con comandos:</b> " + h(label)
    return text


_old_v66_admin_private_block_markup = admin_private_block_markup
def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    markup = _old_v66_admin_private_block_markup(chat_id, block, page)
    if block != "recurrentes":
        return markup
    old_rows = [list(row) for row in getattr(markup, "inline_keyboard", [])]
    insert_row = [InlineKeyboardButton("⚙️ Comandos permitidos en botones", callback_data=f"cfg|rec_cmds|{chat_id}|recurrentes")]
    # Lo ponemos antes de los botones de pie si existen.
    if old_rows:
        old_rows.insert(max(0, len(old_rows)-1), insert_row)
    else:
        old_rows.append(insert_row)
    return InlineKeyboardMarkup(old_rows)


_old_v66_recurring_detail_text = recurring_detail_text
def recurring_detail_text(chat_id: int, rid: int) -> str:  # type: ignore[override]
    base = _old_v66_recurring_detail_text(chat_id, rid)
    row = recurring_find(chat_id, rid)
    if not row:
        return base
    buttons = row.get("buttons") if isinstance(row.get("buttons"), list) else []
    if not buttons:
        return base
    allowed = set(_v66_allowed_rec_commands(chat_id))
    cmd_buttons = [str(b.get("cmd")) for b in buttons if isinstance(b, dict) and b.get("cmd")]
    if cmd_buttons:
        ok = [c for c in cmd_buttons if _v66_clean_cmd_name(c) in allowed]
        blocked = [c for c in cmd_buttons if _v66_clean_cmd_name(c) not in allowed]
        base += f"\n\n<b>Comandos en botones:</b> ✅ {len(ok)} permitidos · ⛔ {len(blocked)} bloqueados"
    return base


async def _v66_rec_cmd_admin_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ""
    parts = data.split("|")
    try:
        action = parts[1]
        chat_id = int(parts[2])
    except Exception:
        await q.answer("Acción inválida", show_alert=True)
        raise ApplicationHandlerStop

    try:
        if not await is_admin(context, chat_id, q.from_user.id):
            await q.answer("Solo administradores.", show_alert=True)
            raise ApplicationHandlerStop

        if action == "rec_cmds":
            await q.answer()
            await q.edit_message_text(_v66_rec_cmds_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v66_rec_cmds_markup(chat_id))
            raise ApplicationHandlerStop

        if action == "rec_cmd_add":
            set_config_pending(q.from_user.id, {"kind": "cfg_rec_cmd_add", "chat_id": chat_id})
            await q.answer()
            await q.edit_message_text(
                "➕ <b>Añadir comando permitido</b>\n\n"
                "Envíame el comando sin barra o con barra.\n"
                "Ejemplos:\n<code>preguntita</code>\n<code>/impostor</code>\n<code>mi_comando_ia</code>",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("❌ Cancelar", callback_data=f"cfg|rec_cmds|{chat_id}|recurrentes")]])
            )
            raise ApplicationHandlerStop

        if action == "rec_cmd_remove" and len(parts) >= 4:
            cmd = _v66_clean_cmd_name(parts[3])
            allowed = [c for c in _v66_allowed_rec_commands(chat_id) if c != cmd]
            _v66_set_allowed_rec_commands(chat_id, allowed)
            await q.answer(f"/{cmd} quitado ✅")
            await q.edit_message_text(_v66_rec_cmds_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v66_rec_cmds_markup(chat_id))
            raise ApplicationHandlerStop

        if action == "rec_cmd_clear":
            _v66_set_allowed_rec_commands(chat_id, [])
            await q.answer("Lista vaciada ✅")
            await q.edit_message_text(_v66_rec_cmds_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v66_rec_cmds_markup(chat_id))
            raise ApplicationHandlerStop

        if action == "rec_cmd_defaults":
            _v66_set_allowed_rec_commands(chat_id, list(_V66_DEFAULT_REC_COMMANDS))
            await q.answer("Básicos restaurados ✅")
            await q.edit_message_text(_v66_rec_cmds_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v66_rec_cmds_markup(chat_id))
            raise ApplicationHandlerStop
    except ApplicationHandlerStop:
        raise
    except Exception:
        logger.exception("Error en configuración de comandos recurrentes: %s", data)
        try:
            await q.answer("Error. Revisa logs.", show_alert=True)
        except Exception:
            pass
        raise ApplicationHandlerStop


async def _v66_rec_cmd_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get("kind") != "cfg_rec_cmd_add":
        return
    chat_id = int(pending.get("chat_id"))
    if not await is_admin(context, chat_id, update.effective_user.id):
        await update.message.reply_text("Solo administradores.")
        pop_config_pending(update.effective_user.id)
        raise ApplicationHandlerStop
    cmd = _v66_clean_cmd_name(update.message.text or "")
    if not cmd:
        await update.message.reply_html("No he detectado un comando válido.")
        raise ApplicationHandlerStop
    allowed = _v66_allowed_rec_commands(chat_id)
    if cmd not in allowed:
        allowed.append(cmd)
        _v66_set_allowed_rec_commands(chat_id, allowed)
    pop_config_pending(update.effective_user.id)
    await update.message.reply_html(
        f"✅ Comando permitido añadido: <code>/{h(cmd)}</code>\n\n" + _v66_rec_cmds_text(chat_id),
        reply_markup=_v66_rec_cmds_markup(chat_id)
    )
    raise ApplicationHandlerStop


async def _v66_recurring_command_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    parts = (q.data or "").split("|", 2)
    if len(parts) < 3:
        await q.answer("Botón inválido", show_alert=True)
        raise ApplicationHandlerStop
    try:
        chat_id = int(parts[1])
    except Exception:
        chat_id = int(q.message.chat_id) if q.message else 0
    cmd = _v66_clean_cmd_name(parts[2])
    user = q.from_user
    if not cmd:
        await q.answer("Comando vacío", show_alert=True)
        raise ApplicationHandlerStop
    if cmd not in set(_v66_allowed_rec_commands(chat_id)):
        await q.answer(f"/{cmd} no está permitido en botones.", show_alert=True)
        raise ApplicationHandlerStop

    try:
        await q.answer("Ejecutando…")
    except Exception:
        pass

    try:
        # Creamos una actualización falsa de mensaje para que el comando use el handler real.
        # Así cualquier comando nuevo que añadas al bot funciona sin tener que duplicar lógica aquí.
        chat_type = "supergroup" if int(chat_id) < 0 else "private"
        title = get_chat_title(chat_id) if 'get_chat_title' in globals() else str(chat_id)
        fake_update_id = int(time.time() * 1000) % 2147483647
        msg_id = int(getattr(q.message, "message_id", 0) or fake_update_id)
        payload = {
            "update_id": fake_update_id,
            "message": {
                "message_id": msg_id,
                "date": int(time.time()),
                "chat": {"id": int(chat_id), "type": chat_type, "title": title},
                "from": {
                    "id": int(user.id),
                    "is_bot": False,
                    "first_name": getattr(user, "first_name", None) or "Usuario",
                    "last_name": getattr(user, "last_name", None) or None,
                    "username": getattr(user, "username", None) or None,
                },
                "text": f"/{cmd}",
                "entities": [{"type": "bot_command", "offset": 0, "length": len(cmd) + 1}],
            },
        }
        fake_update = Update.de_json(payload, context.bot)
        await context.application.process_update(fake_update)
    except Exception:
        logger.exception("Error ejecutando comando permitido desde recurrente: %s", q.data)
        try:
            await q.answer("Error ejecutando el comando. Revisa logs.", show_alert=True)
        except Exception:
            pass
    raise ApplicationHandlerStop


_old_v66_build_application = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_v66_build_application()
    app.add_handler(CallbackQueryHandler(_v66_rec_cmd_admin_callback, pattern=r"^cfg\|rec_cmd"), group=-1300000)
    app.add_handler(CallbackQueryHandler(_v66_recurring_command_callback, pattern=r"^reccmd\|"), group=-1300001)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _v66_rec_cmd_pending_text), group=-1300000)
    logger.info("V66 comandos permitidos configurables para botones recurrentes activado")
    return app


# =========================
# V67 - Fluidez privado, Impostor ON/OFF, IA privada y permisos manuales
# =========================

PRIVATE_PANEL_MESSAGES_V67: Dict[int, set[int]] = {}
PRIVATE_LAST_CHAT_V67: Dict[int, int] = {}


def _v67_track_private_panel(q=None, message=None) -> None:
    try:
        msg = message or (q.message if q else None)
        if not msg or getattr(msg.chat, 'type', '') != 'private':
            return
        PRIVATE_PANEL_MESSAGES_V67.setdefault(int(msg.chat.id), set()).add(int(msg.message_id))
    except Exception:
        pass


async def _v67_delete_private_panels(bot, private_chat_id: int) -> None:
    ids = list(PRIVATE_PANEL_MESSAGES_V67.get(int(private_chat_id), set()))
    for mid in ids:
        try:
            await bot.delete_message(chat_id=int(private_chat_id), message_id=int(mid))
        except Exception:
            pass
    PRIVATE_PANEL_MESSAGES_V67[int(private_chat_id)] = set()


# Asegura que existe get_chat_title para menús nuevos/antiguos.
if 'get_chat_title' not in globals():
    def get_chat_title(chat_id: int) -> str:
        try:
            st = get_state(int(chat_id))
            title = ''
            if isinstance(st.admin_config, dict):
                title = str(st.admin_config.get('chat_title') or st.admin_config.get('title') or '')
            return title or str(chat_id)
        except Exception:
            return str(chat_id)


