# Guarda último grupo seleccionado para poder probar IA/comandos en privado.
_old_v67_admin_private_config_callback = admin_private_config_callback
async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    q = update.callback_query
    data = q.data if q else ''
    if q:
        _v67_track_private_panel(q=q)
    if q and data.startswith('cfg|'):
        parts = data.split('|')
        action = parts[1] if len(parts) > 1 else ''
        try:
            if action in ('open', 'home', 'block', 'save', 'close') and len(parts) >= 3:
                try:
                    PRIVATE_LAST_CHAT_V67[int(q.from_user.id)] = int(parts[2])
                except Exception:
                    pass
            if action in ('close', 'save_close'):
                await q.answer('Panel cerrado ✅')
                await _v67_delete_private_panels(context.bot, int(q.message.chat.id))
                try:
                    await q.message.delete()
                except Exception:
                    pass
                raise ApplicationHandlerStop
            # IMPORTANTE: 'save' NO debe borrar el panel.
            # Deja que el router antiguo lo gestione y edite el mismo mensaje.
            if action == 'save':
                pass
            if action == 'choose_group':
                await q.answer()
                await _v63_render_query(q, '<b>Elige el grupo que quieres configurar:</b>', admin_private_chat_list_markup())
                raise ApplicationHandlerStop
            if action == 'imp_enabled' and len(parts) >= 3:
                chat_id = int(parts[2])
                cfg_set(chat_id, 'impostor_enabled', not bool(cfg_value(chat_id, 'impostor_enabled', True)))
                await q.answer('Impostor actualizado ✅')
                await _v62_render_block(q, chat_id, 'impostor_settings') if '_v62_render_block' in globals() else await _v63_render_query(q, admin_private_block_text(chat_id, 'impostor_settings'), admin_private_block_markup(chat_id, 'impostor_settings'))
                raise ApplicationHandlerStop
            if action == 'perm_add_user' and len(parts) >= 4:
                chat_id = int(parts[2]); module = parts[3]
                set_config_pending(q.from_user.id, {'kind': 'perm_manual_user_v67', 'chat_id': chat_id, 'module': module})
                await q.answer()
                await q.message.reply_html('➕ <b>Añadir usuario permitido</b>\n\nEnvía el <b>ID numérico</b> o el <b>@username</b> del usuario.\n\nEjemplos:\n<code>123456789</code>\n<code>@usuario</code>')
                raise ApplicationHandlerStop
            if action == 'perm_clear_users' and len(parts) >= 4:
                chat_id = int(parts[2]); module = parts[3]
                cfg = admin_cfg(chat_id)
                cfg[f'perm_extra_ids_{module}'] = []
                cfg[f'perm_extra_usernames_{module}'] = []
                save_all_states()
                await q.answer('Usuarios manuales borrados ✅')
                await _v67_render_permissions_for_module(q, chat_id, module)
                raise ApplicationHandlerStop
        except ApplicationHandlerStop:
            raise
        except Exception:
            logger.exception('Error V67 en admin_private_config_callback: %s', data)
            try:
                await q.answer('Error. Revisa logs.', show_alert=True)
            except Exception:
                pass
            raise ApplicationHandlerStop
    return await _old_v67_admin_private_config_callback(update, context)


# Menú principal: garantiza Guardar/Cerrar y Cambiar grupo.
