# Permisos: usuarios manuales extra por módulo.
def _v67_perm_extra_ids(chat_id: int, module: str) -> set[int]:
    vals = cfg_value(chat_id, f'perm_extra_ids_{module}', []) or []
    out = set()
    if isinstance(vals, list):
        for v in vals:
            try:
                out.add(int(v))
            except Exception:
                pass
    return out


def _v67_perm_extra_usernames(chat_id: int, module: str) -> set[str]:
    vals = cfg_value(chat_id, f'perm_extra_usernames_{module}', []) or []
    out = set()
    if isinstance(vals, list):
        for v in vals:
            s = str(v or '').strip().lower().lstrip('@')
            if s:
                out.add(s)
    return out


async def _v67_allowed(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, module: str) -> bool:
    user_id = int(getattr(user, 'id', 0) or 0)
    username = str(getattr(user, 'username', '') or '').lower().lstrip('@')
    if user_id in _v67_perm_extra_ids(chat_id, module):
        return True
    if username and username in _v67_perm_extra_usernames(chat_id, module):
        return True
    return await _v62_allowed(context, chat_id, user_id, module)


async def _v62_guard_command(update: Update, context: ContextTypes.DEFAULT_TYPE, module: str) -> bool:  # type: ignore[override]
    if not update.effective_chat or not update.effective_user or not update.message:
        return False
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == 'private':
        return True
    if not await _v67_allowed(context, chat_id, update.effective_user, module):
        await update.message.reply_html(f'⛔ Este comando está limitado a: <b>{h(_v62_role_label(_v62_module_role(chat_id, module)))}</b>.')
        raise ApplicationHandlerStop
    return True


async def _v67_render_permissions_for_module(q, chat_id: int, module: str) -> None:
    label = dict(PERMISSION_MODULES_V62).get(module, module)
    role = _v62_module_role(chat_id, module)
    ids = sorted(_v67_perm_extra_ids(chat_id, module))
    users = sorted(_v67_perm_extra_usernames(chat_id, module))
    lines = [
        '<b>🔐 Permisos</b>',
        f'Módulo: <b>{h(label)}</b>',
        f'Rol actual: <b>{h(_v62_role_label(role))}</b>',
        '',
        f'Usuarios manuales: <b>{len(ids) + len(users)}</b>',
    ]
    if ids or users:
        lines.append('')
        for x in ids[:10]:
            lines.append(f'• ID <code>{x}</code>')
        for u in users[:10]:
            lines.append(f'• @{h(u)}')
    rows = []
    for rkey, rlabel in PERMISSION_ROLES_V62:
        rows.append([InlineKeyboardButton(('✅ ' if rkey == role else '') + rlabel, callback_data=f'cfg|perm_set|{chat_id}|{module}|{rkey}')])
    rows.append([InlineKeyboardButton('➕ Añadir usuario manual', callback_data=f'cfg|perm_add_user|{chat_id}|{module}')])
    rows.append([InlineKeyboardButton('🧹 Vaciar usuarios manuales', callback_data=f'cfg|perm_clear_users|{chat_id}|{module}')])
    rows.append([InlineKeyboardButton('🔙 Permisos', callback_data=f'cfg|block|{chat_id}|permissions')])
    try:
        await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(rows))
    except Exception:
        await q.message.reply_html('\n'.join(lines), reply_markup=InlineKeyboardMarkup(rows))

