_old_v67_admin_private_config_text = admin_private_config_text
async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:  # type: ignore[override]
    if not update.message or not update.effective_user:
        return False
    pending = get_config_pending(update.effective_user.id)
    if pending and pending.get('kind') == 'perm_manual_user_v67':
        chat_id = int(pending.get('chat_id'))
        module = str(pending.get('module'))
        raw = (update.message.text or update.message.caption or '').strip()
        cfg = admin_cfg(chat_id)
        if raw.startswith('@') or (raw and not raw.lstrip('-').isdigit()):
            username = raw.strip().lower().lstrip('@').split()[0]
            arr = cfg.setdefault(f'perm_extra_usernames_{module}', [])
            if username and username not in arr:
                arr.append(username)
        else:
            try:
                uid = int(raw)
                arr = cfg.setdefault(f'perm_extra_ids_{module}', [])
                if uid not in arr:
                    arr.append(uid)
            except Exception:
                await update.message.reply_html('❌ No entendí el usuario. Envía un ID numérico o @username.')
                return True
        clear_config_pending(update.effective_user.id)
        save_all_states()
        await update.message.reply_html('✅ Usuario añadido a permisos manuales.')
        return True
    return await _old_v67_admin_private_config_text(update, context)


