# =========================
# PATCH V70: Recurrentes con botones separados Inicio / Repetir / Hasta
# =========================
from telegram.ext import ApplicationHandlerStop as _ApplicationHandlerStop_v70
from datetime import timedelta as _td_v70


def _v70_hhmm_to_tuple(value: str) -> tuple[int, int]:
    hh, mm = [int(x) for x in str(value or "00:00").split(":", 1)]
    return max(0, min(23, hh)), max(0, min(59, mm))


def _v70_dt_timestamp(dt) -> int:
    return int(dt.timestamp())


def _v70_next_start_ts_from_schedule(schedule: Dict[str, Any], now_ts: Optional[int] = None) -> int:
    now_ts = int(now_ts or time.time())
    now_dt = _local_dt_v15(now_ts) if '_local_dt_v15' in globals() else _dt_v15.fromtimestamp(now_ts)
    stype = str((schedule or {}).get('type') or '')
    if stype == 'daily':
        hh, mm = _v70_hhmm_to_tuple(str(schedule.get('time', '10:00')))
        cand = now_dt.replace(hour=hh, minute=mm, second=0, microsecond=0)
        if _v70_dt_timestamp(cand) < now_ts:
            cand = cand + _td_v70(days=1)
        return _v70_dt_timestamp(cand)
    if stype == 'weekly':
        hh, mm = _v70_hhmm_to_tuple(str(schedule.get('time', '10:00')))
        days = schedule.get('days') if isinstance(schedule.get('days'), list) else []
        clean_days = [int(x) for x in days] or [int(now_dt.weekday())]
        best = None
        for delta in range(0, 15):
            cand_day = now_dt + _td_v70(days=delta)
            if int(cand_day.weekday()) not in clean_days:
                continue
            cand = cand_day.replace(hour=hh, minute=mm, second=0, microsecond=0)
            if _v70_dt_timestamp(cand) >= now_ts:
                best = cand
                break
        if best is None:
            best = (now_dt + _td_v70(days=7)).replace(hour=hh, minute=mm, second=0, microsecond=0)
        return _v70_dt_timestamp(best)
    if stype == 'date':
        date_s = str(schedule.get('date') or '').strip()
        hh, mm = _v70_hhmm_to_tuple(str(schedule.get('time', '10:00')))
        # Creamos datetime local usando el tzinfo de now_dt si existe.
        y, m, d = [int(x) for x in date_s.split('-', 2)]
        try:
            cand = now_dt.replace(year=y, month=m, day=d, hour=hh, minute=mm, second=0, microsecond=0)
        except Exception:
            cand = _dt_v15(y, m, d, hh, mm)
            if getattr(now_dt, 'tzinfo', None) is not None:
                cand = cand.replace(tzinfo=now_dt.tzinfo)
        return _v70_dt_timestamp(cand)
    raise ValueError('Ese formato no sirve como inicio. Usa: lunes 10:00, diario 10:00 o 2026-05-20 10:00')


def _v70_parse_start_input(raw: str) -> Dict[str, Any]:
    txt = str(raw or '').strip()
    if not txt:
        raise ValueError('Inicio vacío. Ejemplo: lunes 10:00')
    sched = parse_recurring_when(txt)
    stype = str(sched.get('type') or '')
    if stype not in ('daily', 'weekly', 'date'):
        raise ValueError('Para Inicio usa día/hora o fecha/hora. Ejemplos: lunes 10:00 · diario 10:00 · 2026-05-20 10:00')
    start_ts = _v70_next_start_ts_from_schedule(sched)
    label = _schedule_label_v20(sched) if '_schedule_label_v20' in globals() else str(sched.get('label') or txt)
    return {'raw': txt, 'label': label, 'ts': int(start_ts), 'base': sched}


def _v70_parse_until_input(raw: str) -> Dict[str, Any]:
    txt = str(raw or '').strip()
    if not txt:
        raise ValueError('Fecha/hora vacía. Ejemplo: 2026-05-20 18:00')
    sched = parse_recurring_when(txt)
    stype = str(sched.get('type') or '')
    if stype not in ('daily', 'weekly', 'date'):
        raise ValueError('Para Hasta usa fecha/hora o día/hora. Ejemplo recomendado: 2026-05-20 18:00')
    until_ts = _v70_next_start_ts_from_schedule(sched)
    label = _schedule_label_v20(sched) if '_schedule_label_v20' in globals() else str(sched.get('label') or txt)
    return {'raw': txt, 'label': label, 'ts': int(until_ts), 'base': sched}


def _v70_interval_label(seconds: int) -> str:
    if '_human_interval_label_v20' in globals():
        return _human_interval_label_v20(int(seconds))
    if seconds % 3600 == 0:
        hhh = seconds // 3600
        return f'cada {hhh} hora' if hhh == 1 else f'cada {hhh} horas'
    if seconds % 60 == 0:
        mmm = seconds // 60
        return f'cada {mmm} minutos'
    return f'cada {seconds}s'


def _v70_start_interval_label(schedule: Dict[str, Any]) -> str:
    start_label = str(schedule.get('start_label') or 'sin inicio')
    repeat_seconds = int(schedule.get('repeat_seconds') or 3600)
    label = f"desde {start_label} · {_v70_interval_label(repeat_seconds)}"
    if bool(schedule.get('until_enabled')):
        label += f" · hasta {schedule.get('until_label') or 'fecha/hora pendiente'}"
    return label


def _v70_make_start_interval_schedule(row: Dict[str, Any], *, start: Optional[Dict[str, Any]] = None, repeat_seconds: Optional[int] = None, until: Optional[Dict[str, Any]] = None, until_enabled: Optional[bool] = None) -> Dict[str, Any]:
    old = row.get('schedule') if isinstance(row.get('schedule'), dict) else {}
    if str(old.get('type') or '') != 'start_interval':
        old_start_label = str(row.get('schedule_label') or old.get('label') or 'pendiente')
        old = {
            'type': 'start_interval',
            'start_raw': str(old.get('label') or old_start_label),
            'start_label': old_start_label,
            'start_ts': int(time.time()),
            'repeat_seconds': 3600,
            'until_enabled': False,
            'until_ts': 0,
            'until_label': '',
        }
    sched = dict(old)
    if start is not None:
        sched['start_raw'] = start['raw']
        sched['start_label'] = start['label']
        sched['start_ts'] = int(start['ts'])
        sched['start_base'] = start.get('base')
    if repeat_seconds is not None:
        sched['repeat_seconds'] = max(60, int(repeat_seconds))
    if until is not None:
        sched['until_raw'] = until['raw']
        sched['until_label'] = until['label']
        sched['until_ts'] = int(until['ts'])
        sched['until_base'] = until.get('base')
        sched['until_enabled'] = True
    if until_enabled is not None:
        sched['until_enabled'] = bool(until_enabled)
    sched['type'] = 'start_interval'
    sched['label'] = _v70_start_interval_label(sched)
    return sched


def recurring_due(row: Dict[str, Any], now_ts: int) -> bool:  # type: ignore[override]
    if not bool(row.get('enabled', True)):
        return False
    sched = row.get('schedule') if isinstance(row.get('schedule'), dict) else {}
    if str(sched.get('type') or '') != 'start_interval':
        return _old_recurring_due_v70(row, now_ts) if '_old_recurring_due_v70' in globals() else False
    try:
        now_ts = int(now_ts)
        if bool(sched.get('until_enabled')):
            until_ts = int(sched.get('until_ts') or 0)
            if until_ts and now_ts > until_ts:
                row['enabled'] = False
                save_all_states()
                return False
        start_ts = int(sched.get('start_ts') or 0)
        if start_ts and now_ts < start_ts:
            return False
        repeat = max(60, int(sched.get('repeat_seconds') or 3600))
        last = int(row.get('last_sent_ts') or 0)
        if last <= 0:
            return True
        return now_ts - last >= repeat
    except Exception:
        logger.exception('Error en recurrente start_interval: %s', row.get('id'))
        return False


# Guardamos la versión anterior de recurring_due si aún no la guardamos.
if '_old_recurring_due_v70' not in globals():
    try:
        _old_recurring_due_v70 = globals().get('recurring_due')  # se sobrescribe justo abajo si existía antes del parche
    except Exception:
        _old_recurring_due_v70 = None

# Reasignamos correctamente: como acabamos de definir recurring_due, si _old apunta a esta misma, buscamos una copia anterior común.
try:
    if _old_recurring_due_v70 is recurring_due:
        # En algunos despliegues no se puede recuperar; dejamos fallback a la versión V15 si existiera en closure no accesible.
        _old_recurring_due_v70 = None
except Exception:
    pass

# Para no perder la lógica anterior por el orden del parche, reconstruimos fallback para schedules viejos.
def _v70_old_due_fallback(row: Dict[str, Any], now_ts: int) -> bool:
    if not bool(row.get('enabled', True)):
        return False
    sched = row.get('schedule') if isinstance(row.get('schedule'), dict) else {}
    last = int(row.get('last_sent_ts', 0) or 0)
    stype = str(sched.get('type') or '')
    now_dt = _local_dt_v15(now_ts) if '_local_dt_v15' in globals() else _dt_v15.fromtimestamp(now_ts)
    if stype == 'interval':
        sec = max(30, int(sched.get('seconds', 3600) or 3600))
        return now_ts - last >= sec
    if stype == 'daily':
        hhmm = str(sched.get('time', '21:00'))
        day_key = now_dt.strftime('%Y-%m-%d')
        if row.get('last_day') == day_key:
            return False
        try:
            hh, mm = _v70_hhmm_to_tuple(hhmm)
            return (now_dt.hour, now_dt.minute) >= (hh, mm)
        except Exception:
            return False
    if stype == 'weekly':
        hhmm = str(sched.get('time', '21:00'))
        days = sched.get('days') if isinstance(sched.get('days'), list) else []
        try:
            if int(now_dt.weekday()) not in [int(x) for x in days]:
                return False
            week_key = f"{now_dt.strftime('%G-%V')}-{now_dt.weekday()}"
            if row.get('last_week_key') == week_key:
                return False
            hh, mm = _v70_hhmm_to_tuple(hhmm)
            return (now_dt.hour, now_dt.minute) >= (hh, mm)
        except Exception:
            return False
    if stype == 'date':
        hhmm = str(sched.get('time', '21:00'))
        date_s = str(sched.get('date', ''))
        if row.get('last_date_key') == date_s:
            return False
        if now_dt.strftime('%Y-%m-%d') != date_s:
            return False
        try:
            hh, mm = _v70_hhmm_to_tuple(hhmm)
            return (now_dt.hour, now_dt.minute) >= (hh, mm)
        except Exception:
            return False
    return False

# Sobrescribimos de nuevo con fallback seguro.
def recurring_due(row: Dict[str, Any], now_ts: int) -> bool:  # type: ignore[override]
    sched = row.get('schedule') if isinstance(row.get('schedule'), dict) else {}
    if str(sched.get('type') or '') == 'start_interval':
        if not bool(row.get('enabled', True)):
            return False
        try:
            now_ts = int(now_ts)
            if bool(sched.get('until_enabled')):
                until_ts = int(sched.get('until_ts') or 0)
                if until_ts and now_ts > until_ts:
                    row['enabled'] = False
                    save_all_states()
                    return False
            start_ts = int(sched.get('start_ts') or 0)
            if start_ts and now_ts < start_ts:
                return False
            repeat = max(60, int(sched.get('repeat_seconds') or 3600))
            last = int(row.get('last_sent_ts') or 0)
            return True if last <= 0 else (now_ts - last >= repeat)
        except Exception:
            logger.exception('Error en recurrente start_interval: %s', row.get('id'))
            return False
    return _v70_old_due_fallback(row, now_ts)


def _v70_update_row_schedule(row: Dict[str, Any], schedule: Dict[str, Any]) -> None:
    row['schedule'] = schedule
    row['schedule_label'] = schedule.get('label', '')
    row['last_sent_ts'] = 0
    row.pop('last_day', None)
    row.pop('last_week_key', None)
    row.pop('last_date_key', None)
    save_all_states()


